import Decimal from "decimal.js";

const Exact = Decimal.clone({precision: 100, rounding: Decimal.ROUND_HALF_UP, toExpNeg: -100, toExpPos: 100});
export const definedRatioVersion = "2026.09.20-v1";
export type DefinedRatioInput = {
  numerator: string | null;
  denominator: string | null;
  limit: string | null;
  comparator: "lt" | "lte" | "gt" | "gte";
  /** Arithmetic convention only. Contractual definitions and source rights are upstream. */
  convention: "positive_denominator_unrounded_comparison";
};

/** A displayed quotient must never decide a boundary. Cross-products preserve exact
 * comparison, including strict limits, within the bounded decimal input domain.
 * A zero/negative denominator is not an economic pass or a legal breach. */
export function evaluateDefinedRatio(input: DefinedRatioInput) {
  if (!input || input.convention !== "positive_denominator_unrounded_comparison"
    || !["lt", "lte", "gt", "gte"].includes(input.comparator)) throw new Error("defined_ratio_convention_required");
  const parse = (value: string | null) => {
    if (value === null) return null;
    if (typeof value !== "string" || !/^-?\d{1,24}(?:\.\d{1,12})?$/.test(value)) throw new Error("defined_ratio_invalid_decimal");
    return new Exact(value);
  };
  const numerator = parse(input.numerator); const denominator = parse(input.denominator); const limit = parse(input.limit);
  const common = {engineVersion: definedRatioVersion, operands: structuredClone(input),
    displayRounding: "18_decimal_places_half_up" as const,
    comparisonRounding: "none_cross_products" as const, certifiesContractualCompliance: false as const};
  const missing = (["numerator", "denominator", "limit"] as const).filter(k => input[k] === null);
  if (missing.length) return {...common, status: "missing_inputs" as const, missing, ratio: null, margin: null, satisfiesDefinedBoundary: null, crossProducts: null};
  if (denominator!.lte(0)) return {...common, status: "nonpositive_denominator" as const, missing, ratio: null, margin: null, satisfiesDefinedBoundary: null, crossProducts: null};
  const threshold = limit!.times(denominator!);
  const comparison = numerator!.comparedTo(threshold);
  const upper = input.comparator === "lt" || input.comparator === "lte";
  const satisfies = input.comparator === "lt" ? comparison < 0 : input.comparator === "lte" ? comparison <= 0
    : input.comparator === "gt" ? comparison > 0 : comparison >= 0;
  const marginNumerator = upper ? threshold.minus(numerator!) : numerator!.minus(threshold);
  const display = (value: Decimal) => value.toDecimalPlaces(18, Exact.ROUND_HALF_UP).toFixed();
  return {...common, status: "calculated" as const, missing,
    ratio: display(numerator!.div(denominator!)), margin: display(marginNumerator.div(denominator!)),
    satisfiesDefinedBoundary: satisfies,
    crossProducts: {numerator: numerator!.toFixed(), limitTimesDenominator: threshold.toFixed(), marginNumerator: marginNumerator.toFixed()}};
}

packages/credit-playbook/src/material-fi.content:
import type {ArchetypeId} from "./types";

/**
 * One economic requirement may be stated under more than one canonical path.
 *
 * Current gross debt is the clearest example: a debt schedule can state it as
 * `debt.total_gross`, while financial statements state it under a dated historical or interim
 * path. Requiring one spelling would turn a complete case into a false gap. The requirement is
 * therefore named once and discharged by any of its accepted patterns.
 */
export type MaterialFieldRequirement = {
  id: string;
  anyOf: readonly string[];
};

const requirement = (id: string, ...anyOf: string[]): MaterialFieldRequirement => ({id, anyOf});

const common: readonly MaterialFieldRequirement[] = [
  requirement("company_legal_name", "company.legal_name"),
  requirement("requested_amount", "transaction.requested_amount"),
  requirement(
    "current_gross_debt",
    "debt.total_gross",
    "interim_financials.*.gross_debt",
    "historical_financials.*.gross_debt",
  ),
];

const perArchetype: Readonly<Record<ArchetypeId, readonly MaterialFieldRequirement[]>> = {
  growth_expansion: [
    requirement("project_total_cost", "project.total_cost"),
    requirement("project_investment", "project.investments.*.amount"),
    requirement("desired_term", "transaction.desired_term_months"),
    requirement("collateral_capacity", "collateral.total_capacity"),
    requirement("minimum_dscr", "projections.minimum_dscr"),
  ],
  working_capital: [
    requirement("receivables_capacity", "collateral.receivables_capacity"),
    requirement("customer_concentration", "customers.top_customers.*.share_pct"),
  ],
  refinance: [
    requirement("debt_maturity", "debt.instruments.*.maturity"),
    requirement("debt_rate", "debt.instruments.*.rate"),
  ],
  acquisition: [
    requirement("post_transaction_leverage", "leverage.post_transaction_net_debt_ebitda"),
  ],
  equipment_finance: [
    requirement("project_total_cost", "project.total_cost"),
    requirement("asset_appraisal", "collateral.assets.*.appraisal_value"),
  ],
  venture_debt: [
    requirement("runway", "company.runway_months"),
    requirement("net_revenue_retention", "company.net_revenue_retention"),
    requirement("last_equity_round", "company.last_equity_round.amount"),
  ],
  other: [],
};

export function materialFieldRequirements(archetypeId: ArchetypeId): MaterialFieldRequirement[] {
  return [...common, ...perArchetype[archetypeId]];
}

const regexpFor = (pattern: string): RegExp => {
  const escaped = pattern.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\\\*/g, "[^.]+");
  return new RegExp(`^${escaped}$`);
};

export function fieldMatchesPattern(fieldPath: string, pattern: string): boolean {
  return regexpFor(pattern).test(fieldPath);
}

export function requirementIsSatisfied(
  requirement: MaterialFieldRequirement,
  availableFieldPaths: ReadonlySet<string>,
): boolean {
  return requirement.anyOf.some((pattern) =>
    [...availableFieldPaths].some((fieldPath) => fieldMatchesPattern(fieldPath, pattern)),
  );
}

export function fieldsForRequirement<T extends {key: {fieldPath: string}}>(
  requirement: MaterialFieldRequirement,
  facts: readonly T[],
): T[] {
  return facts.filter((fact) => requirement.anyOf.some((pattern) => fieldMatchesPattern(fact.key.fieldPath, pattern)));
}

packages/financial-core/src/depreciation.content:
import Decimal from "decimal.js";

/** Annual straight-line vintage schedule, with zero residual value explicitly selected.
 * A half-year vintage depreciates half in its first and last year; never beyond cost.
 */
export function calculateAnnualCapexDepreciation(input: {
  amountsByYear: readonly string[];
  usefulLifeYears: number;
  convention: "next_period" | "half_year";
  yearIndex: number;
}): {value: string; vintages: readonly {yearIndex:number;amount:string;factor:string;depreciation:string}[]} {
  if (!Number.isSafeInteger(input.usefulLifeYears) || input.usefulLifeYears <= 0) throw new RangeError("useful life must be positive whole years");
  if (!Number.isSafeInteger(input.yearIndex) || input.yearIndex < 0 || input.yearIndex >= input.amountsByYear.length) throw new RangeError("year index outside capex schedule");
  if (!["next_period", "half_year"].includes(input.convention)) throw new RangeError("unsupported depreciation convention");
  const vintages = input.amountsByYear.map((value, yearIndex) => {
    const amount = new Decimal(value);
    if (!amount.isFinite() || amount.lt(0)) throw new RangeError("capex must be finite and nonnegative");
    const age = input.yearIndex - yearIndex;
    const factor = input.convention === "next_period"
      ? age >= 1 && age <= input.usefulLifeYears ? "1" : "0"
      : age < 0 || age > input.usefulLifeYears ? "0" : age === 0 || age === input.usefulLifeYears ? "0.5" : "1";
    return {yearIndex, amount:amount.toFixed(), factor, depreciation:amount.div(input.usefulLifeYears).mul(factor).toFixed()};
  });
  return {value:vintages.reduce((total,row)=>total.plus(row.depreciation),new Decimal(0)).toFixed(),vintages};
}

packages/credit-playbook/src/instruments.content:
import type {TransactionRoute} from "@offroad/credit-ontology";

import {routeForLegacyInstrument} from "./taxonomy";
import type {ArchetypeId} from "./types";

/**
 * The instruments a Brazilian private-credit desk actually places, as data a banker can
 * disagree with.
 *
 * An archetype says what the money is for; an instrument says what paper carries it, who may
 * issue it, what it costs to set up, how it is taxed, and what the law requires. The two are
 * different questions, and the product answered only the first. A limitada cannot issue a
 * debenture; a CRA needs agribusiness receivables as backing; a CRI needs real estate; a FIDC
 * needs a receivables base worth securitising; venture debt needs equity sponsors behind it.
 * Telling a company which papers its profile admits, and why the others are closed, is the
 * first structuring sentence a desk says.
 */

/**
 * `debenture_476` is a legacy storage key. Stored pricing observations (the check constraint of
 * `pricing_observations.instrument`), stored structure proposals and the fingerprints bound to their
 * decisions, the Case 01 v4 executor snapshot and the Rede Horizonte gold carry it, so the key stays.
 * The paper it names is the debenture offered to professional investors under the automatic rite of
 * Resolução CVM 160/2022, which revoked ICVM 476 from 02/01/2023; none of the ICVM 476 rules apply.
 */
export type InstrumentId =
  | "ccb"
  | "nce"
  | "debenture_476"
  | "debenture_160"
  | "nota_comercial"
  | "cra"
  | "cri"
  | "fidc"
  | "venture_debt"
  | "finame"
  | "leasing";

export type LegalForm = "sa" | "ltda" | "other";

export type IssuerProfile = {
  legalForm: LegalForm;
  archetypeId: ArchetypeId;
  /** Requested amount in reais, as a decimal string. */
  amount: string;
  /** Whether the company's revenue is predominantly agribusiness (producer, cooperative, agro trade). */
  agribusiness?: boolean;
  /** Whether the use of proceeds is real estate (construction, acquisition, or backed by property receivables). */
  realEstate?: boolean;
  /** Whether an equity sponsor (venture fund) is on the cap table. */
  ventureBacked?: boolean;
  /** Whether the proceeds buy identifiable equipment or vehicles. */
  equipment?: boolean;
  /** Whether the company has a receivables base large enough to securitise (as a fraction of the ask). */
  receivablesCoverage?: string;
  /** Whether the proceeds fund exports. */
  exports?: boolean;
};

export type OfferAudience = "professional" | "qualified" | "general_public";

/**
 * How a security the company itself issues reaches investors under Resolução CVM 160/2022, in force
 * since 02/01/2023. It revoked ICVM 400 and ICVM 476, and with ICVM 476 the caps of 75 investors
 * approached and 50 subscribers. The audience decides whether the issuer must be registered with the
 * CVM; the registration rite follows from the issuer and the audience.
 */
export type OfferRegime = {
  rule: "cvm_160";
  rite: "automatic" | "automatic_or_ordinary";
  audiences: readonly OfferAudience[];
  issuerRegistrationRequired: boolean;
};

/**
 * Credit IOF on the company's side under Decreto 6.306/2007, as amended through 2025: the general
 * rate (0,0082% a day capped at 365 days plus 0,38%, art. 7º), an exemption (art. 9º), a zero rate
 * (art. 8º), not levied (securities, leases and receivables assignments sit outside the credit IOF),
 * or depends on the paper when the route uses more than one.
 */
export type CreditIof = "general_rate" | "exempt" | "zero_rate" | "not_levied" | "depends_on_paper";

export type Instrument = {
  id: InstrumentId;
  labels: {pt: string; en: string};
  description: {pt: string; en: string};
  /** Who may issue it. */
  legalForms: readonly LegalForm[];
  /** Smallest ticket that makes the set-up cost worth it, in reais. */
  minimumAmount: string;
  /** Typical tenor range in months. */
  tenorMonths: {min: number; max: number};
  /** Typical all-in cost band over CDI, in basis points, before the warrant or guarantee. */
  spreadOverCdiBps: {min: number; max: number};
  /** Structuring, registration and agent costs, as a fraction of the amount, typical. */
  setupCostPct: string;
  /** Who buys this paper. */
  buyers: readonly string[];
  /** Tax treatment the company and the investor read first. */
  tax: {pt: string; en: string};
  /** Credit IOF the company pays on this paper. */
  creditIof: CreditIof;
  /**
   * Offer regime of a security the company itself issues (debentures and the nota comercial).
   * Absent for bilateral credit, leases, development-bank lines, venture debt, whose paper varies,
   * and paper a securitisation company or a fund issues (CRA, CRI, FIDC quotas).
   */
  offerRegime?: OfferRegime;
  /** What the law and the market require before it exists. */
  requirements: {pt: string; en: string}[];
  /** The archetypes this paper usually serves. */
  archetypes: readonly ArchetypeId[];
};

