export type InstrumentVerdict = {
  instrument: Instrument;
  /** Orthogonal economic interpretation of the legacy commercial route. */
  route: TransactionRoute;
  eligible: boolean;
  /** Why it is open or closed for this issuer, in one sentence each. */
  reasons: {pt: string; en: string}[];
};

/**
 * Which papers this issuer may place, and why each of the others is closed.
 *
 * Eligibility is a property of the issuer and the use, never of appetite: a limitada cannot
 * issue a debenture whatever its numbers, a CRA needs agribusiness credit behind it, a FIDC
 * needs receivables worth selling. The verdicts are meant to be read, so a closed door says
 * what would open it.
 */
export function instrumentVerdicts(profile: IssuerProfile): InstrumentVerdict[] {
  const amount = Number(profile.amount);
  return instruments.map((instrument) => {
    const reasons: {pt: string; en: string}[] = [];
    let eligible = true;
    if (!instrument.legalForms.includes(profile.legalForm)) {
      eligible = false;
      // The legal form in words in both languages, never its key ("sa", "ltda").
      reasons.push(bi(
        `Exige ${instrument.legalForms.map((form) => ({sa: "sociedade anônima", ltda: "limitada", other: "outra forma"})[form]).join(" ou ")}; a companhia é ${({sa: "sociedade anônima", ltda: "limitada", other: "de outra forma"})[profile.legalForm]}.`,
        `Requires ${instrument.legalForms.map((form) => ({sa: "a sociedade anônima", ltda: "a limitada", other: "another legal form"})[form]).join(" or ")}; the company ${({sa: "is a sociedade anônima", ltda: "is a limitada", other: "has another legal form"})[profile.legalForm]}.`,
      ));
    }
    if ((instrument.id === "debenture_476" || instrument.id === "debenture_160") && profile.legalForm === "ltda") {
      reasons.push(bi("A limitada não emite debênture; a nota comercial e a CCB são as rotas equivalentes.", "A limitada cannot issue debentures; the commercial note and the CCB are the equivalent routes."));
    }
    if (instrument.id === "nota_comercial" && profile.legalForm === "other") {
      reasons.push(bi("A cooperativa também emite nota comercial; confirmada essa forma societária, a rota se abre.", "A cooperative may also issue a commercial note; once that legal form is confirmed, the route opens."));
    }
    if (amount < Number(instrument.minimumAmount)) {
      eligible = false;
      reasons.push(bi(`Abaixo do tíquete mínimo em que o custo de estruturação compensa (R$ ${(Number(instrument.minimumAmount) / 1e6).toFixed(0)} milhões).`, `Below the minimum ticket at which the set-up cost pays (R$ ${(Number(instrument.minimumAmount) / 1e6).toFixed(0)} million).`));
    }
    if (instrument.id === "cra" && !profile.agribusiness) {
      eligible = false;
      reasons.push(bi("Sem lastro do agronegócio: a receita da companhia não decorre da cadeia agro.", "No agribusiness backing: the company's revenue does not come from the agribusiness chain."));
    }
    if (instrument.id === "cri" && !profile.realEstate) {
      eligible = false;
      reasons.push(bi("Sem lastro imobiliário na destinação ou nas garantias.", "No real estate backing in the use of proceeds or the security."));
    }
    if (instrument.id === "nce" && !profile.exports) {
      eligible = false;
      reasons.push(bi("Sem vínculo com exportação.", "No export link."));
    }
    if (instrument.id === "fidc" && (profile.receivablesCoverage === undefined || Number(profile.receivablesCoverage) < 1.2)) {
      eligible = false;
      reasons.push(bi("Base de recebíveis abaixo de 1,2x o pedido; um FIDC precisa de carteira para vender.", "Receivables base under 1.2x the ask; a FIDC needs a portfolio to sell."));
    }
    if (instrument.id === "venture_debt" && !profile.ventureBacked) {
      eligible = false;
      reasons.push(bi("Sem investidor institucional de equity no cap table.", "No institutional equity investor on the cap table."));
    }
    if ((instrument.id === "finame" || instrument.id === "leasing") && !profile.equipment) {
      eligible = false;
      reasons.push(bi("A destinação não é bem identificável (máquina, veículo, equipamento).", "The use of proceeds is not an identifiable asset (machine, vehicle, equipment)."));
    }
    if (!instrument.archetypes.includes(profile.archetypeId)) {
      reasons.push(bi("Papel pouco usual para esta operação; possível, mas fora da prática.", "Unusual paper for this operation; possible, but outside practice."));
    }
    if (eligible && reasons.length === 0) reasons.push(bi("Elegível pela forma societária, pelo tíquete e pela destinação.", "Eligible by legal form, ticket and use."));
    return {instrument, route: routeForLegacyInstrument(instrument.id, profile), eligible, reasons};
  });
}

packages/financial-core/src/assumption-u.content:
import Decimal from "decimal.js";

/** Converts a declared presentation unit; never guesses a unit or parses prose. */
export function normalizeDeclaredAssumptionValue(value:string,unit:"percent"|"currency"|"days"|"multiple"|"quantity"|"index"):{value:string;input:string;conversion:"percent_to_ratio"|"identity"} {
  if(!/^-?\d+(?:\.\d+)?$/.test(value)||value.length>80)throw new RangeError("a bounded decimal value is required");
  if(!["percent","currency","days","multiple","quantity","index"].includes(unit))throw new RangeError("declared unit required");
  const ExactDecimal=Decimal.clone({precision:120});
  const numeric=new ExactDecimal(value);
  if(!numeric.isFinite())throw new RangeError("finite value required");
  return {value:unit==="percent"?numeric.div(100).toFixed():numeric.toFixed(),input:value,conversion:unit==="percent"?"percent_to_ratio":"identity"};
}

packages/financial-core/src/indexed-debt.content:
import Decimal from "decimal.js";

export type IndexedDebtTreatment = "not_applicable" | "cash_paid" | "capitalized_principal";
export type CouponTreatment = "cash_paid" | "capitalized_principal";
/** Average principal deducts half of the principal amortized before this period's
 * coupon capitalization. It is a declared period convention, not a dated accrual. */
export type CouponBase = "opening_principal" | "indexed_principal" | "average_principal";

export type IndexedDebtPeriodInput = {
  period: string;
  /** Effective rate for this exact period, after the contractual lag and interpolation. */
  indexationRate: Decimal.Value;
  /** Effective contractual coupon/spread for this exact period. */
  couponRate: Decimal.Value;
  drawdown?: Decimal.Value;
  scheduledPrincipal?: Decimal.Value;
  prepayment?: Decimal.Value;
  /** Repay the full indexed principal plus this period's capitalized coupon. Mutually exclusive with
   * explicit scheduled principal and prepayment. This is required for inflation-linked bullets:
   * the contractual nominal is updated by the index and the updated amount, not the opening
   * nominal alone, is settled at maturity. */
  repayAll?: boolean;
};

export type IndexedDebtInstrumentInput = {
  instrumentId: string;
  openingPrincipal: Decimal.Value;
  indexer: "none" | "IPCA" | "CDI" | "SOFR" | "fixed" | "other";
  indexationTreatment: IndexedDebtTreatment;
  couponTreatment: CouponTreatment;
  couponBase: CouponBase;
  periods: readonly IndexedDebtPeriodInput[];
};

export type IndexedDebtServiceRow = {
  period: string;
  openingPrincipal: string;
  drawdown: string;
  indexationAccrued: string;
  indexationPaid: string;
  indexationCapitalized: string;
  couponBase: string;
  couponAccrued: string;
  couponPaid: string;
  couponCapitalized: string;
  scheduledPrincipal: string;
  prepayment: string;
  cashDebtService: string;
  nonCashDebtIncrease: string;
  financeExpense: string;
  closingPrincipal: string;
};

export type IndexedDebtSchedule = {
  instrumentId: string;
  rows: IndexedDebtServiceRow[];
  totalCashDebtService: string;
  totalFinanceExpense: string;
  totalIndexationCapitalized: string;
  totalCouponCapitalized: string;
};

const d = (value: Decimal.Value) => new Decimal(value);
const canonical = (value: Decimal) => value.toDecimalPlaces(8).toFixed();

function nonNegative(value: Decimal.Value, label: string): Decimal {
  const parsed = d(value);
  if (!parsed.isFinite()) throw new RangeError(`${label} must be finite`);
  if (parsed.isNegative()) throw new RangeError(`${label} cannot be negative`);
  return parsed;
}

function contractualRate(value: Decimal.Value, label: string): Decimal {
  const parsed = d(value);
  if (!parsed.isFinite() || parsed.lte(-1)) throw new RangeError(`${label} must be finite and greater than -100%`);
  return parsed;
}

/**
 * Builds a contractual debt roll-forward without conflating indexation with cash interest.
 *
 * Brazilian inflation-linked debt measured why the distinction is structural: IPCA may update
 * principal, may be settled in cash, or may not apply at all. Coupon/interest can independently
 * be paid or capitalized. The two non-cash components increase the debt balance and finance
 * expense but do not enter cash debt service in the accrual period.
 */
export function buildIndexedDebtSchedule(input: IndexedDebtInstrumentInput): IndexedDebtSchedule {
  if (!input.instrumentId.trim()) throw new RangeError("instrument id is required");
  if (input.periods.length === 0) throw new RangeError("at least one debt period is required");
  if (input.indexer === "none" && input.indexationTreatment !== "not_applicable") {
    throw new RangeError("a non-indexed instrument cannot accrue indexation");
  }
  if (input.indexer !== "none" && input.indexationTreatment === "not_applicable"
      && input.periods.some((period) => !d(period.indexationRate).isZero())) {
    throw new RangeError("non-zero indexation requires an explicit treatment");
  }

  let principal = nonNegative(input.openingPrincipal, "opening principal");
  let totalCashDebtService = new Decimal(0);
  let totalFinanceExpense = new Decimal(0);
  let totalIndexationCapitalized = new Decimal(0);
  let totalCouponCapitalized = new Decimal(0);
  const seenPeriods = new Set<string>();
  const rows: IndexedDebtServiceRow[] = [];

  for (const period of input.periods) {
    if (!period.period.trim() || seenPeriods.has(period.period)) throw new RangeError(`duplicate or empty debt period: ${period.period}`);
    seenPeriods.add(period.period);
    const openingPrincipal = principal;
    const drawdown = nonNegative(period.drawdown ?? 0, "drawdown");
    const indexationRate = contractualRate(period.indexationRate, "indexation rate");
    const couponRate = contractualRate(period.couponRate, "coupon rate");
    const scheduledRequested = nonNegative(period.scheduledPrincipal ?? 0, "scheduled principal");
    const prepaymentRequested = nonNegative(period.prepayment ?? 0, "prepayment");
    if (period.repayAll && (!scheduledRequested.isZero() || !prepaymentRequested.isZero())) {
      throw new RangeError(`repayAll cannot be combined with scheduled principal or prepayment in ${period.period}`);
    }
    const preIndexationPrincipal = openingPrincipal.plus(drawdown);
    const indexationAccrued = input.indexationTreatment === "not_applicable"
      ? new Decimal(0)
      : preIndexationPrincipal.mul(indexationRate);
    const indexationPaid = input.indexationTreatment === "cash_paid" ? indexationAccrued : new Decimal(0);
    const indexationCapitalized = input.indexationTreatment === "capitalized_principal" ? indexationAccrued : new Decimal(0);
    const indexedPrincipal = preIndexationPrincipal.plus(indexationCapitalized);
    const requestedPrincipal = period.repayAll ? indexedPrincipal : scheduledRequested.plus(prepaymentRequested);
    if (requestedPrincipal.gt(indexedPrincipal)) throw new RangeError(`principal payment exceeds outstanding balance in ${period.period}`);
    const prepayment = prepaymentRequested;
    const couponBase = input.couponBase === "opening_principal"
      ? preIndexationPrincipal
      : input.couponBase === "average_principal"
        ? indexedPrincipal.minus(requestedPrincipal.div(2))
        : indexedPrincipal;
    const couponAccrued = Decimal.max(couponBase, 0).mul(couponRate);
    const couponPaid = input.couponTreatment === "cash_paid" ? couponAccrued : new Decimal(0);
    const couponCapitalized = input.couponTreatment === "capitalized_principal" ? couponAccrued : new Decimal(0);
    // Compute the coupon on its declared base before settling it. Including PIK in
    // that base through the final payment would create a circular average-principal formula.
    const paidPrincipal = period.repayAll ? indexedPrincipal.plus(couponCapitalized) : requestedPrincipal;
    const scheduledPrincipal = period.repayAll ? paidPrincipal : scheduledRequested;
    principal = indexedPrincipal.plus(couponCapitalized).minus(paidPrincipal);
    const cashDebtService = indexationPaid.plus(couponPaid).plus(paidPrincipal);
    const nonCashDebtIncrease = indexationCapitalized.plus(couponCapitalized);
    const financeExpense = indexationAccrued.plus(couponAccrued);

    totalCashDebtService = totalCashDebtService.plus(cashDebtService);
    totalFinanceExpense = totalFinanceExpense.plus(financeExpense);
    totalIndexationCapitalized = totalIndexationCapitalized.plus(indexationCapitalized);
    totalCouponCapitalized = totalCouponCapitalized.plus(couponCapitalized);
    rows.push({
      period: period.period,
      openingPrincipal: canonical(openingPrincipal),
      drawdown: canonical(drawdown),
      indexationAccrued: canonical(indexationAccrued),
      indexationPaid: canonical(indexationPaid),
      indexationCapitalized: canonical(indexationCapitalized),
      couponBase: canonical(couponBase),
      couponAccrued: canonical(couponAccrued),
      couponPaid: canonical(couponPaid),
      couponCapitalized: canonical(couponCapitalized),
      scheduledPrincipal: canonical(scheduledPrincipal),
      prepayment: canonical(prepayment),
      cashDebtService: canonical(cashDebtService),
      nonCashDebtIncrease: canonical(nonCashDebtIncrease),
      financeExpense: canonical(financeExpense),
      closingPrincipal: canonical(principal),
    });
  }

  return {
    instrumentId: input.instrumentId,
    rows,
    totalCashDebtService: canonical(totalCashDebtService),
    totalFinanceExpense: canonical(totalFinanceExpense),
    totalIndexationCapitalized: canonical(totalIndexationCapitalized),
    totalCouponCapitalized: canonical(totalCouponCapitalized),
  };
}

export function aggregateIndexedDebtSchedules(schedules: readonly IndexedDebtSchedule[], confirmedDebtFreePeriods?: readonly string[]) {
  if(confirmedDebtFreePeriods && (schedules.length>0||new Set(confirmedDebtFreePeriods).size!==confirmedDebtFreePeriods.length||confirmedDebtFreePeriods.some(period=>!period.trim())))throw new RangeError("debt-free periods require an empty instrument ledger and unique explicit periods");
  const periods = confirmedDebtFreePeriods ? [...confirmedDebtFreePeriods] : [...new Set(schedules.flatMap((schedule) => schedule.rows.map((row) => row.period)))].sort();
  return periods.map((period) => {
    const rows = schedules.flatMap((schedule) => schedule.rows.filter((row) => row.period === period));
    const sum = (key: keyof Pick<IndexedDebtServiceRow, "openingPrincipal" | "drawdown" | "indexationAccrued" | "indexationPaid" | "indexationCapitalized" | "couponAccrued" | "couponPaid" | "couponCapitalized" | "scheduledPrincipal" | "prepayment" | "cashDebtService" | "nonCashDebtIncrease" | "financeExpense" | "closingPrincipal">) =>
      canonical(rows.reduce((total, row) => total.plus(row[key]), new Decimal(0)));
    return {
      period,
      openingPrincipal: sum("openingPrincipal"),
      drawdown: sum("drawdown"),
      indexationAccrued: sum("indexationAccrued"),
      indexationPaid: sum("indexationPaid"),
      indexationCapitalized: sum("indexationCapitalized"),
      couponAccrued: sum("couponAccrued"),
      couponPaid: sum("couponPaid"),
      couponCapitalized: sum("couponCapitalized"),
      scheduledPrincipal: sum("scheduledPrincipal"),
      prepayment: sum("prepayment"),
      cashDebtService: sum("cashDebtService"),
      nonCashDebtIncrease: sum("nonCashDebtIncrease"),
      financeExpense: sum("financeExpense"),
      closingPrincipal: sum("closingPrincipal"),
    };
  });
}

packages/credit-playbook/src/taxonomy.ts.content:
import {transactionRouteSchema, type TransactionRoute} from "@offroad/credit-ontology";

import type {InstrumentId, IssuerProfile} from "./instruments";
import type {ArchetypeId} from "./types";

const capitalNeed = (archetypeId: ArchetypeId): TransactionRoute["capitalNeed"] =>
  archetypeId === "other" ? "other" : archetypeId;

/**
 * Compatibility boundary from the original instrument menu to the orthogonal taxonomy.
 *
 * The legacy id remains stable for existing screens and snapshots. The returned route is the
 * economic interpretation used by new analysis, evals and artifacts. No consumer should infer
 * that a vehicle such as a FIDC is the company's obligation merely because the old menu used one
 * id for the commercial route.
 */
export function routeForLegacyInstrument(id: InstrumentId, profile: IssuerProfile): TransactionRoute {
  const common = {capitalNeed: capitalNeed(profile.archetypeId)};

  switch (id) {
    case "ccb":
      return transactionRouteSchema.parse({...common, repaymentSources: ["operating_cash_flow"], obligationInstruments: ["ccb"], structureMechanisms: ["bilateral_loan"], capitalVehicles: ["bank_balance_sheet", "credit_fund"], capitalProviderTypes: ["bank", "credit_fund_manager"], distributionRoutes: ["bilateral_private"]});
    case "nce":
      return transactionRouteSchema.parse({...common, repaymentSources: ["operating_cash_flow"], obligationInstruments: ["nce"], structureMechanisms: ["bilateral_loan"], capitalVehicles: ["bank_balance_sheet"], capitalProviderTypes: ["bank"], distributionRoutes: ["bilateral_private"]});
    case "debenture_476":
      return transactionRouteSchema.parse({...common, repaymentSources: ["operating_cash_flow"], obligationInstruments: ["debenture"], distributedSecurities: ["debenture"], structureMechanisms: ["private_placement"], capitalVehicles: ["credit_fund", "family_office", "insurance_balance_sheet"], capitalProviderTypes: ["asset_manager", "institutional_investor", "family_office", "insurer"], distributionRoutes: ["private_distribution"]});
    case "debenture_160":
      return transactionRouteSchema.parse({...common, repaymentSources: ["operating_cash_flow"], obligationInstruments: ["debenture"], distributedSecurities: ["debenture"], structureMechanisms: ["public_offering"], capitalVehicles: ["credit_fund", "family_office", "insurance_balance_sheet"], capitalProviderTypes: ["asset_manager", "institutional_investor", "family_office", "insurer"], distributionRoutes: ["public_distribution"]});
    case "nota_comercial":
      return transactionRouteSchema.parse({...common, repaymentSources: ["operating_cash_flow"], obligationInstruments: ["commercial_note"], distributedSecurities: ["commercial_note"], structureMechanisms: ["private_placement"], capitalVehicles: ["credit_fund", "family_office", "bank_balance_sheet"], capitalProviderTypes: ["asset_manager", "credit_fund_manager", "family_office", "bank"], distributionRoutes: ["private_distribution"]});
    case "cra":
      return transactionRouteSchema.parse({...common, repaymentSources: ["receivables_collection", "operating_cash_flow"], assetBackings: ["receivables"], obligationInstruments: ["other"], distributedSecurities: ["cra"], structureMechanisms: ["securitization"], capitalVehicles: ["securitization_company", "credit_fund"], capitalProviderTypes: ["securitization_company", "asset_manager", "institutional_investor"], distributionRoutes: ["institutional_sounding"]});
    case "cri":
      return transactionRouteSchema.parse({...common, repaymentSources: ["asset_cash_flow", "operating_cash_flow"], assetBackings: ["real_estate"], obligationInstruments: ["other"], distributedSecurities: ["cri"], structureMechanisms: ["securitization"], capitalVehicles: ["securitization_company", "credit_fund"], capitalProviderTypes: ["securitization_company", "asset_manager", "institutional_investor"], distributionRoutes: ["institutional_sounding"], securityEnhancements: ["fiduciary_lien_real_estate"]});
    case "fidc":
      return transactionRouteSchema.parse({...common, repaymentSources: ["receivables_collection"], assetBackings: ["receivables"], obligationInstruments: ["receivables_assignment"], distributedSecurities: ["fidc_senior_quota", "fidc_subordinated_quota"], structureMechanisms: ["receivables_purchase"], capitalVehicles: ["fidc"], capitalProviderTypes: ["fidc_manager"], distributionRoutes: ["bilateral_private"], securityEnhancements: ["overcollateralization", "subordination"]});
    case "venture_debt":
      return transactionRouteSchema.parse({...common, repaymentSources: ["sponsor_support", "operating_cash_flow"], obligationInstruments: ["other"], structureMechanisms: ["venture_debt"], capitalVehicles: ["credit_fund"], capitalProviderTypes: ["credit_fund_manager"], distributionRoutes: ["bilateral_private"]});
    case "finame":
      return transactionRouteSchema.parse({...common, repaymentSources: ["operating_cash_flow"], assetBackings: ["equipment"], obligationInstruments: ["finame_on_lending"], structureMechanisms: ["asset_finance"], capitalVehicles: ["development_bank_program", "bank_balance_sheet"], capitalProviderTypes: ["development_bank", "bank"], distributionRoutes: ["bilateral_private"], securityEnhancements: ["fiduciary_lien_equipment"]});
    case "leasing":
      return transactionRouteSchema.parse({...common, repaymentSources: ["operating_cash_flow"], assetBackings: ["equipment"], obligationInstruments: ["leasing"], structureMechanisms: ["asset_finance"], capitalVehicles: ["bank_balance_sheet"], capitalProviderTypes: ["bank"], distributionRoutes: ["bilateral_private"], securityEnhancements: ["fiduciary_lien_equipment"]});
  }
}

packages/credit-playbook/src/covenants.t.content:
/**
 * The covenants a Brazilian private-credit indenture actually carries, as data a lawyer can
 * mark up.
 *
 * A term sheet that lists "dívida líquida / EBITDA" has named a ratio, not a covenant. A
 * covenant is the ratio, its accounting definition (what counts as debt, which EBITDA, which
 * period), how often it is tested and on what statements, what happens when it is breached
 * (cure period, waiver, step-up, acceleration), and the carve-outs. Writing the ten usual
 * ones down once means every term sheet says the same thing the same way, and a desk that
 * disagrees changes one line.
 */

export type CovenantId =
  | "net_leverage"
  | "interest_coverage"
  | "dscr"
  | "minimum_cash"
  | "minimum_arr"
  | "additional_debt"
  | "restricted_payments"
  | "change_of_control"
  | "cross_default"
  | "information";

export type CovenantKind = "financial" | "negative" | "event" | "information";

export type CovenantDefinition = {
  id: CovenantId;
  kind: CovenantKind;
  labels: {pt: string; en: string};
  /** The accounting definition the indenture writes, so two parties read one number. */
  definition: {pt: string; en: string};
  /** How often it is tested and on what. */
  test: {pt: string; en: string};
  /** What happens on breach: cure, waiver, step-up, acceleration. */
  breach: {pt: string; en: string};
  /** The usual carve-outs. */
  carveOuts: {pt: string; en: string}[];
  /** Archetypes where the covenant is customary. */
  usual: readonly string[];
};

const bi = (pt: string, en: string) => ({pt, en});

export const covenantCatalogue: readonly CovenantDefinition[] = [
  {
    id: "net_leverage", kind: "financial",
    labels: bi("Dívida líquida / EBITDA", "Net debt / EBITDA"),
    definition: bi("Dívida líquida: empréstimos, financiamentos, debêntures, notas e arrendamentos financeiros (IFRS 16 excluído ou incluído conforme acordado, declarado aqui), mais derivativos passivos líquidos, menos caixa, equivalentes e aplicações financeiras de liquidez imediata. EBITDA: lucro operacional antes de resultado financeiro, IR/CSLL, depreciação e amortização, dos últimos doze meses, ajustado apenas por itens não recorrentes listados na escritura com teto anual.", "Net debt: loans, financings, debentures, notes and finance leases (IFRS 16 excluded or included as agreed, stated here), plus net derivative liabilities, less cash, equivalents and immediately liquid financial investments. EBITDA: operating profit before financial result, income taxes, depreciation and amortisation, over the last twelve months, adjusted only for non-recurring items listed in the indenture with an annual cap."),
    test: bi("Trimestral sobre ITR revisado e anual sobre demonstrações auditadas, no prazo de 45 dias do fechamento; primeira aferição no primeiro trimestre completo após o desembolso.", "Quarterly on reviewed interim statements and annually on audited statements, within 45 days of the close; first test on the first full quarter after disbursement."),
    breach: bi("Cura de 30 dias por aporte de capital ou redução de dívida (equity cure, no máximo duas vezes na vida do papel, não consecutivas); waiver por assembleia de credores com quórum de 2/3; na falta, vencimento antecipado declarável por maioria.", "30-day cure by equity injection or debt reduction (equity cure, at most twice over the life of the paper, not consecutive); waiver by a creditors' meeting with a two-thirds quorum; failing that, acceleration declarable by majority."),
    carveOuts: [bi("Dívida subordinada aos credores do papel fora da dívida líquida.", "Debt subordinated to the paper's creditors excluded from net debt."), bi("Aquisições: EBITDA pro forma dos últimos doze meses da adquirida.", "Acquisitions: pro forma last-twelve-months EBITDA of the target.")],
    usual: ["growth_expansion", "working_capital", "refinance", "acquisition", "equipment_finance"],
  },
  {
    id: "interest_coverage", kind: "financial",
    labels: bi("EBITDA / despesa financeira líquida", "EBITDA / net interest expense"),
    definition: bi("Despesa financeira líquida: juros incorridos sobre a dívida (competência), menos receitas financeiras de aplicações, excluindo variação cambial e marcação de derivativos.", "Net interest expense: interest accrued on debt, less financial income from investments, excluding foreign exchange variation and derivative marking."),
    test: bi("Trimestral, acumulado de doze meses.", "Quarterly, on a trailing twelve-month basis."),
    breach: bi("Cura de 30 dias; waiver por 2/3; step-up de remuneração de 50 bps enquanto descumprido, se assim negociado.", "30-day cure; waiver by two-thirds; a 50 bps remuneration step-up while in breach, where so negotiated."),
    carveOuts: [bi("Juros capitalizados em obra fora da despesa até a entrada em operação.", "Interest capitalised during construction excluded until the asset enters operation.")],
    usual: ["growth_expansion", "refinance", "acquisition"],
  },
  {
    id: "dscr", kind: "financial",
    labels: bi("Índice de cobertura do serviço da dívida (DSCR)", "Debt service coverage ratio (DSCR)"),
    definition: bi("Caixa disponível para o serviço da dívida (EBITDA menos IR/CSLL pagos, menos capex de manutenção, mais ou menos variação do capital de giro) dividido pelo serviço da dívida (principal mais juros pagos) do período.", "Cash available for debt service (EBITDA less income taxes paid, less maintenance capex, plus or minus working capital change) over debt service (principal plus interest paid) in the period."),
    test: bi("Anual sobre auditado, a partir do primeiro exercício completo após a carência.", "Annually on audited statements, from the first full year after grace."),
    breach: bi("Retenção de caixa em conta vinculada (cash sweep) até recomposição; vencimento antecipado se abaixo do piso por dois testes consecutivos.", "Cash trapped in a blocked account (cash sweep) until restored; acceleration if below the floor on two consecutive tests."),
    carveOuts: [bi("Capex de expansão financiado por equity fora do cálculo.", "Expansion capex funded by equity excluded from the calculation.")],
    usual: ["growth_expansion", "equipment_finance"],
  },
  {
    id: "minimum_cash", kind: "financial",
    labels: bi("Caixa mínimo", "Minimum cash"),
    definition: bi("Caixa, equivalentes e aplicações de liquidez imediata em contas da emissora, aferidos no último dia do mês; para empresa em queima, expresso em meses de queima líquida média dos últimos três meses.", "Cash, equivalents and immediately liquid investments in the issuer's accounts, measured on the last day of the month; for a cash-burning company, expressed as months of the last three months' average net burn."),
    test: bi("Mensal, por declaração do diretor financeiro com extratos; trimestral conferido no ITR.", "Monthly, by the CFO's certificate with bank statements; quarterly checked against the interim statements."),
    breach: bi("Cura de 15 dias por aporte; abaixo do piso por 30 dias, vencimento antecipado declarável.", "15-day cure by injection; below the floor for 30 days, acceleration declarable."),
    carveOuts: [bi("Caixa restrito de garantias e depósitos judiciais fora da conta.", "Restricted cash for security and judicial deposits excluded.")],
    usual: ["venture_debt", "working_capital"],
  },
  {
    id: "minimum_arr", kind: "financial",
    labels: bi("ARR mínimo", "Minimum ARR"),
    definition: bi("Receita recorrente anualizada: MRR contratado do último mês do trimestre vezes doze, excluindo serviços, implantação e contratos em aviso de cancelamento.", "Annualised recurring revenue: contracted MRR of the quarter's last month times twelve, excluding services, implementation and contracts under cancellation notice."),
    test: bi("Trimestral, sobre export por cliente assinado pelo diretor financeiro; piso com folga de 20% sobre o plano.", "Quarterly, on the per-customer export signed by the CFO; floor at 20% below plan."),
    breach: bi("Renegociação do cronograma com step-up de 100 bps; dois trimestres abaixo do piso, vencimento antecipado declarável.", "Schedule renegotiation with a 100 bps step-up; two quarters below the floor, acceleration declarable."),
    carveOuts: [],
    usual: ["venture_debt"],
  },
  {
    id: "additional_debt", kind: "negative",
    labels: bi("Limitação de nova dívida", "Limitation on additional debt"),
