import Decimal from "decimal.js";

import {decimal, full, receivablesPoolKernelsVersion, requireNonNegative, requireUnitInterval, safeRatio, ZERO, type ReceivablesPoolKernelTrace} from "./pool-shared";

export type ReceivablesPoolBorrowingBase = {
  version: typeof receivablesPoolKernelsVersion;
  adjustedEligibleBalance: string;
  totalOutstanding: string;
  /** Adjusted eligible balance over the total outstanding; zero when the portfolio is empty. */
  eligibleShare: string;
  requestedFacility: string;
  maximumByAdvanceRate: string;
  maximumByOvercollateralization: string;
  supportedFacility: string;
  bindingConstraint: "advance_rate" | "overcollateralization" | "both";
  requestCoveredBySupportedFacility: boolean;
  /** Adjusted eligible balance over the requested facility; zero when nothing is requested. */
  overcollateralizationAtRequest: string;
  requiredOvercollateralization: string;
  totalCapital: string;
  subordinateCapital: string;
  actualSubordinationRate: string;
  requiredSubordinationRate: string;
  reserveTarget: string;
  trace: ReceivablesPoolKernelTrace;
};

/**
 * Sizes the facility a concentration-adjusted eligible base supports: the lesser of the base times
 * the advance rate and the base divided by the minimum overcollateralization, compared with the
 * request (which never inflates the base). Actual subordination is mezzanine plus subordinated
 * capital over the whole capital stack; the reserve target is the senior amount times the reserve rate.
 */
export function calculateReceivablesPoolBorrowingBase(input: {
  adjustedEligibleBalance: string;
  totalOutstanding: string;
  requestedFacility: string;
  advanceRate: string;
  requiredOvercollateralization: string;
  requiredSubordinationRate: string;
  actualSeniorAmount: string;
  actualMezzanineAmount: string;
  actualSubordinatedAmount: string;
  reserveRate: string;
}): ReceivablesPoolBorrowingBase {
  const adjusted = requireNonNegative("adjustedEligibleBalance", input.adjustedEligibleBalance);
  const total = requireNonNegative("totalOutstanding", input.totalOutstanding);
  const requested = requireNonNegative("requestedFacility", input.requestedFacility);
  const advanceRate = requireUnitInterval("advanceRate", input.advanceRate);
  const requiredOc = decimal(input.requiredOvercollateralization);
  if (!requiredOc.isFinite() || requiredOc.lt(1)) throw new RangeError("requiredOvercollateralization must be at least one");
  const requiredSubordination = requireUnitInterval("requiredSubordinationRate", input.requiredSubordinationRate);
  const senior = requireNonNegative("actualSeniorAmount", input.actualSeniorAmount);
  const mezzanine = requireNonNegative("actualMezzanineAmount", input.actualMezzanineAmount);
  const subordinated = requireNonNegative("actualSubordinatedAmount", input.actualSubordinatedAmount);
  const reserveRate = requireUnitInterval("reserveRate", input.reserveRate);

  const maximumByAdvance = adjusted.times(advanceRate);
  const maximumByOc = adjusted.div(requiredOc);
  const supported = Decimal.min(maximumByAdvance, maximumByOc);
  const totalCapital = senior.plus(mezzanine).plus(subordinated);
  const subordinateCapital = mezzanine.plus(subordinated);
  const actualSubordination = safeRatio(subordinateCapital, totalCapital);
  const overcollateralization = requested.isZero() ? ZERO : adjusted.div(requested);
  const reserveTarget = senior.times(reserveRate);
  const eligibleShare = safeRatio(adjusted, total);
  const bindingConstraint = maximumByAdvance.eq(maximumByOc) ? "both" : maximumByAdvance.lt(maximumByOc) ? "advance_rate" : "overcollateralization";
  return {
    version: receivablesPoolKernelsVersion,
    adjustedEligibleBalance: full(adjusted),
    totalOutstanding: full(total),
    eligibleShare: full(eligibleShare),
    requestedFacility: full(requested),
    maximumByAdvanceRate: full(maximumByAdvance),
    maximumByOvercollateralization: full(maximumByOc),
    supportedFacility: full(supported),
    bindingConstraint,
    requestCoveredBySupportedFacility: supported.gte(requested),
    overcollateralizationAtRequest: full(overcollateralization),
    requiredOvercollateralization: full(requiredOc),
    totalCapital: full(totalCapital),
    subordinateCapital: full(subordinateCapital),
    actualSubordinationRate: full(actualSubordination),
    requiredSubordinationRate: full(requiredSubordination),
    reserveTarget: full(reserveTarget),
    trace: {
      id: "receivables.pool_borrowing_base",
      formula: "supported = min(adjusted * advanceRate, adjusted / requiredOvercollateralization); ocAtRequest = adjusted / requested; subordination = (mezzanine + subordinated) / (senior + mezzanine + subordinated); reserveTarget = senior * reserveRate",
      operands: {
        adjustedEligibleBalance: full(adjusted),
        advanceRate: full(advanceRate),
        requiredOvercollateralization: full(requiredOc),
        requestedFacility: full(requested),
        actualSeniorAmount: full(senior),
        actualMezzanineAmount: full(mezzanine),
        actualSubordinatedAmount: full(subordinated),
        reserveRate: full(reserveRate),
      },
      result: full(supported),
    },
  };
}

packages/credit-playbook/src/voice-filte.content:
/**
 * Deterministic voice filter compiled from two sources:
 *
 * - Source A: procedure section "N4. Voz e três níveis de afirmação", lines 207 to 219 of
 *   `knowledge/procedures/capital/prepare-capital-structure-decision.md`, plus the T1 sentence
 *   (line 227) that keeps the composition labels off the interface.
 * - Source B: the founder's banker filter, the list of constructions a banker never writes.
 *
 * It inspects strings that reach a reader and reports the patterns the house refuses. It never
 * rewrites a string and never judges the substance behind it: N4 and Q2 both say that a clean
 * lexical pass does not certify a good opinion. Every rule is data (what it matches, how severe
 * it is, which paragraph justifies it), so a reviewer can read the policy without reading code.
 *
 * The characters the rules ban are built from their code points on purpose: the house style
 * test walks every package for the literal, and the rule that names a character must not be an
 * offender.
 * The offending example words live in the test corpus, as N4 asks, not here.
 */

export const VOICE_FILTER_VERSION = "2026.09.24-v1";

export type VoiceChannel = "packet" | "screen" | "catalogue";
export type VoiceSeverity = "block" | "warn";
export type VoiceRuleId = `VF-${string}`;
/** The slice of a string a rule is tested against; also the unit a finding reports. */
export type VoiceScope = "text" | "line" | "sentence";
export type VoiceLevel = "fato" | "leitura" | "recomendacao" | "indeterminado";

export type VoiceString = {id: string; text: string};

export type VoiceRule = {
  id: VoiceRuleId;
  /** Stable snake_case code, in the style of the conduct policy findings. */
  code: string;
  severity: VoiceSeverity;
  /** The source paragraph that justifies the rule, quoting the phrase where the source names it. */
  origin: string;
  description: string;
  scope: VoiceScope;
  /** The unit fires when any pattern matches it; a string pattern is a case-sensitive literal. */
  patterns: readonly (RegExp | string)[];
  /** A unit that also matches this is exempt: the number that turns "não fecha" into a calculation. */
  unless?: RegExp;
  /** What the reader sees next to the finding, in pt-BR like the conduct policy messages. */
  message: string;
};

/**
 * Shaped after `ConductFinding` (ruleId, code, severity, message) so both audits can be listed
 * together. The severity vocabulary is the one the voice brief fixes, `block` or `warn`; a
 * consumer merging into a conduct audit maps `warn` to `review`.
 */
export type VoiceFinding = {
  ruleId: VoiceRuleId;
  code: string;
  severity: VoiceSeverity;
  message: string;
  channel: VoiceChannel;
  /** The id given with the string, or its index when the caller passed plain strings. */
  stringId: string;
  /** The matched text with a little context, so a reader can locate it without the rule. */
  excerpt: string;
};

const EM_DASH = String.fromCodePoint(0x2014);
const EN_DASH = String.fromCodePoint(0x2013);
const N4 = "prepare-capital-structure-decision.md, N4";
const T1 = "prepare-capital-structure-decision.md, T1";
const FOUNDER = "founder's banker filter";

/**
 * `\b` in a JavaScript regex only knows ASCII letters, so "ótimo" and "quê" never sit on a
 * word boundary. These lookarounds are the Unicode-aware equivalent.
 */
const NOT_WORD_BEFORE = "(?<![\\p{L}\\p{N}_])";
const NOT_WORD_AFTER = "(?![\\p{L}\\p{N}_])";

function words(source: string, flags: "u" | "iu" = "iu"): RegExp {
  return new RegExp(`${NOT_WORD_BEFORE}(?:${source})${NOT_WORD_AFTER}`, flags);
}

/** A digit anywhere in the unit: the account behind "não fecha" or behind a verdict. */
const HAS_NUMBER = /\d/u;

export const voiceRules: readonly VoiceRule[] = [
  {
    id: "VF-01",
    code: "em_dash",
    severity: "block",
    origin: `${N4} line 219: "travessões em qualquer texto entregue"; ${FOUNDER}: U+2014`,
    description: "The em dash (U+2014) anywhere in a delivered string.",
    scope: "text",
    patterns: [EM_DASH],
    message: "Travessão (U+2014) proibido em qualquer texto entregue.",
  },
  {
    id: "VF-02",
    code: "en_dash",
    severity: "block",
    origin: `${FOUNDER}: U+2013`,
    description: "The en dash (U+2013) anywhere in a delivered string.",
    scope: "text",
    patterns: [EN_DASH],
    message: "Meia-risca (U+2013) proibida em qualquer texto entregue.",
  },
  {
    id: "VF-03",
    code: "emoji",
    severity: "block",
    origin: `${N4} line 219: "emoji"; ${FOUNDER}: emoji`,
    description: "A character with default emoji presentation, or a pictograph forced into emoji presentation by U+FE0F.",
    scope: "text",
    patterns: [/\p{Emoji_Presentation}/u, /\p{Extended_Pictographic}\u{FE0F}/u],
    message: "Emoji proibido em texto entregue.",
  },
  {
    id: "VF-04",
    code: "ai_self_reference",
    severity: "block",
    origin: `${N4} line 219: "como IA"; ${FOUNDER}: "como IA", "como modelo de linguagem"`,
    description: "The system speaking as an AI or as a language model, in pt-BR or en-US. The acronym is matched case-sensitively so that the verb form \"como ia\" is left alone.",
    scope: "text",
    patterns: [
      words("[Cc]omo\\s+(?:uma\\s+)?IA", "u"),
      words("como\\s+(?:um\\s+)?modelo\\s+de\\s+linguagem"),
      words("[Aa]s\\s+an\\s+AI", "u"),
      words("as\\s+a\\s+language\\s+model"),
    ],
    message: "O texto fala como IA ou como modelo de linguagem.",
  },
  {
    id: "VF-05",
    code: "filler",
    severity: "block",
    origin: `${N4} line 219: "vale destacar", "ótima pergunta"; ${FOUNDER}: "vale destacar", "ótima pergunta"`,
    description: "Conversational filler the house refuses, with the en-US equivalent of the compliment.",
    scope: "text",
    patterns: [words("vale\\s+destacar|ótima\\s+pergunta|great\\s+question")],
    message: "Preenchimento de conversa proibido pela voz da casa.",
  },
  {
    id: "VF-06",
    code: "third_party_certainty",
    severity: "block",
