import Decimal from "decimal.js";

const Exact = Decimal.clone({precision: 100, rounding: Decimal.ROUND_HALF_UP});
export const numericRepresentationVersion = "2026.09.20-v1";
export type NumericRepresentation = "reported_in_declared_scale" | "already_in_currency_units";

/** Explicit representation is an upstream evidence decision, never inferred here. No FX,
 * percentage conversion or rounding. An unsupported result is rejected rather than truncated.
 */
export function normalizeCurrencyRepresentation(input: {values: readonly string[]; declaredScale: string; representation: NumericRepresentation}) {
  if (!input.values.length || input.values.length > 2000) throw new Error("numeric_representation_value_limit");
  if (typeof input.declaredScale !== "string" || !/^\d{1,24}(?:\.\d{1,16})?$/.test(input.declaredScale)
    || new Exact(input.declaredScale).lte(0)) throw new Error("numeric_representation_invalid_scale");
  if (!["reported_in_declared_scale", "already_in_currency_units"].includes(input.representation)) throw new Error("numeric_representation_required");
  const factor = input.representation === "reported_in_declared_scale" ? new Exact(input.declaredScale) : new Exact(1);
  const values = input.values.map(value => {
    if (typeof value !== "string" || !/^-?\d{1,24}(?:\.\d{1,8})?$/.test(value)) throw new Error("numeric_representation_invalid_value");
    const normalized = new Exact(value).times(factor).toFixed();
    if (!/^-?\d{1,24}(?:\.\d{1,8})?$/.test(normalized)) throw new Error("numeric_representation_result_outside_domain");
    return normalized;
  });
  return {schemaVersion: "currency-representation.v1" as const, engineVersion: numericRepresentationVersion,
    operands: {values: [...input.values], declaredScale: input.declaredScale, representation: input.representation},
    factor: factor.toFixed(), outputScale: "1" as const, values, rounding: "none" as const};
}

packages/financial-core/src/operating-ca.content:
import Decimal from "decimal.js";

const Exact = Decimal.clone({precision: 100, rounding: Decimal.ROUND_HALF_UP});
export const operatingCashProjectionVersion = "2026.09.20-v1";
export type OperatingWorkingCapital = {
  receivables: string; inventory: string; otherOperatingAssets: string;
  payables: string; otherOperatingLiabilities: string;
};
export type OperatingProjectionPeriod = {
  id: string; startDate: string; endDate: string;
  /** Net revenue; sales taxes/returns must already be excluded under the adopted definition. */
  revenue: {mode: "amount"; amount: string} | {mode: "drivers"; quantity: string; netUnitPrice: string};
  variableOperatingExpense: string; fixedOperatingExpense: string;
  /** Signed bridge from EBITDA: add non-cash expenses/subtract non-cash income included above.
   * Excludes working capital, financing, capex and taxes reported in their own operands. */
  nonCashEbitdaAdjustment: string;
  closingWorkingCapital: OperatingWorkingCapital;
  cashTaxesPaid: string; cashTaxRefunds: string;
  maintenanceCapexPaid: string; growthCapexPaid: string;
};
export type OperatingCashProjectionInput = {
  currency: string; openingDate: string; endDate: string;
  openingWorkingCapital: OperatingWorkingCapital;
  periods: readonly OperatingProjectionPeriod[];
  convention: "accrual_ebitda_to_cash_before_financing";
};
const keys = ["receivables", "inventory", "otherOperatingAssets", "payables", "otherOperatingLiabilities"] as const;
function number(value: string, signed = false) {
  if (typeof value !== "string" || !(signed ? /^-?\d{1,24}(?:\.\d{1,8})?$/ : /^\d{1,24}(?:\.\d{1,8})?$/).test(value)) throw new Error("operating_projection_invalid_amount");
  return new Exact(value);
}
function date(value: string) {
  if (typeof value !== "string" || !/^[1-9]\d{3}-\d{2}-\d{2}$/.test(value)) throw new Error("operating_projection_invalid_date");
  const d = new Date(`${value}T00:00:00Z`);
  if (!Number.isFinite(d.getTime()) || d.toISOString().slice(0, 10) !== value) throw new Error("operating_projection_invalid_date");
  return d;
}
function next(value: string) {const d = date(value); d.setUTCDate(d.getUTCDate() + 1); return d.toISOString().slice(0, 10);}
function balance(value: OperatingWorkingCapital) {
  if (!value || Object.keys(value).sort().join() !== [...keys].sort().join()) throw new Error("operating_projection_working_capital_required");
  keys.forEach(key => number(value[key]));
  return number(value.receivables).plus(value.inventory).plus(value.otherOperatingAssets).minus(value.payables).minus(value.otherOperatingLiabilities);
}
function exact(value: Decimal) {
  const result = value.toFixed();
  if (!/^-?\d{1,48}(?:\.\d{1,16})?$/.test(result)) throw new Error("operating_projection_result_outside_domain");
  return result;
}

/** Period budget only. Does not infer payment dates, liquidity within the period, tax rules,
 * source completeness or a contractual CFADS definition. Missing operands are rejected;
 * upstream orchestration must return a gap, never fill them with zero. */
export function buildOperatingCashProjection(input: OperatingCashProjectionInput) {
  date(input.openingDate); date(input.endDate);
  if (input.endDate <= input.openingDate || !/^[A-Z]{3}$/.test(input.currency)
    || input.convention !== "accrual_ebitda_to_cash_before_financing") throw new Error("operating_projection_context_required");
  if (!input.periods.length || input.periods.length > 240) throw new Error("operating_projection_period_limit");
  let priorEnd = input.openingDate; let opening = structuredClone(input.openingWorkingCapital);
  let previousWorkingCapital = balance(opening);
  let cumulative = new Exact(0);
  const ids = new Set<string>();
  const rows = input.periods.map(p => {
    date(p.startDate); date(p.endDate);
    if (typeof p.id !== "string" || !p.id.trim() || p.id.length > 160 || ids.has(p.id)) throw new Error("operating_projection_period_identity");
    ids.add(p.id);
    if (p.startDate !== next(priorEnd) || p.endDate < p.startDate || p.endDate > input.endDate) throw new Error("operating_projection_period_coverage");
    priorEnd = p.endDate;
    let revenue: Decimal;
    if (p.revenue?.mode === "amount" && Object.keys(p.revenue).sort().join() === "amount,mode") revenue = number(p.revenue.amount);
    else if (p.revenue?.mode === "drivers" && Object.keys(p.revenue).sort().join() === "mode,netUnitPrice,quantity") revenue = number(p.revenue.quantity).times(number(p.revenue.netUnitPrice));
    else throw new Error("operating_projection_revenue_convention");
    const ebitda = revenue.minus(number(p.variableOperatingExpense)).minus(number(p.fixedOperatingExpense));
    const closing = balance(p.closingWorkingCapital);
    const change = closing.minus(previousWorkingCapital);
    const cashBeforeFinancing = ebitda.plus(number(p.nonCashEbitdaAdjustment, true)).minus(change)
      .minus(number(p.cashTaxesPaid)).plus(number(p.cashTaxRefunds))
      .minus(number(p.maintenanceCapexPaid)).minus(number(p.growthCapexPaid));
    cumulative = cumulative.plus(cashBeforeFinancing);
    const row = {periodId: p.id, startDate: p.startDate, endDate: p.endDate,
      operands: {openingWorkingCapital: opening, ...structuredClone(p)},
      netRevenue: exact(revenue), ebitda: exact(ebitda), openingNetWorkingCapital: exact(previousWorkingCapital),
      closingNetWorkingCapital: exact(closing), changeInNetWorkingCapital: exact(change),
      cashBeforeFinancing: exact(cashBeforeFinancing), cumulativeCashBeforeFinancing: exact(cumulative)};
    opening = structuredClone(p.closingWorkingCapital); previousWorkingCapital = closing;
    return row;
  });
  if (priorEnd !== input.endDate) throw new Error("operating_projection_period_coverage");
  return {schemaVersion: "operating-cash-projection.v1" as const, engineVersion: operatingCashProjectionVersion,
    currency: input.currency, openingDate: input.openingDate, endDate: input.endDate, convention: input.convention,
    rows, totalCashBeforeFinancing: exact(cumulative), rounding: "none" as const,
    exclusions: ["intraperiod_liquidity", "financing", "contractual_cfads", "tax_rule_inference", "source_completeness"] as const};
}

packages/credit-playbook/src/method-run-.content:
import {createHash} from "node:crypto";
import {readFileSync, readdirSync} from "node:fs";
import {join} from "node:path";

import {z} from "zod";

/**
 * A recorded execution of a deterministic method, on record. The rungs above `ai_reviewed` ask for
 * gold, adversarial and consistency runs; for a method whose contract declares zero model calls the
 * honest run is an executed one, not a transcript of a conversation. Each record names the exact
 * cases, their expectation, the observed decision and the input/output fingerprints, so a test can
 * re-execute the harness and prove that the record still reproduces instead of trusting prose.
 */
const sha256Schema = z.string().regex(/^[a-f0-9]{64}$/);

export const deterministicRunKindSchema = z.enum(["gold", "adversarial", "consistency"]);
export type DeterministicRunKind = z.infer<typeof deterministicRunKindSchema>;

export const deterministicMethodRunCaseSchema = z.object({
  id: z.string().min(1).max(160),
  /** What the case asserts, declared independently from the implementation. */
  expectation: z.string().min(1).max(400),
  /** What the execution produced for that assertion. */
  observed: z.string().min(1).max(400),
  inputFingerprint: sha256Schema,
  outputFingerprint: sha256Schema,
  passed: z.boolean(),
}).strict();
export type DeterministicMethodRunCase = z.infer<typeof deterministicMethodRunCaseSchema>;

export const deterministicMethodRunSchema = z.object({
  schemaVersion: z.literal("deterministic-method-run.v1"),
  runId: z.string().regex(/^[a-z0-9][a-z0-9_.-]{2,120}$/),
  kind: deterministicRunKindSchema,
  /** A recorded run is evidence of execution, never a human or model approval. */
  humanApproval: z.literal(false),
  method: z.object({id: z.string().min(1), version: z.string().min(1)}).strict(),
  executor: z.object({module: z.string().min(1), exportName: z.string().min(1)}).strict(),
  /** The reproducible harness: re-running it must rebuild the same case evidence. */
  harness: z.object({module: z.string().min(1), exportName: z.string().min(1)}).strict(),
  run: z.object({
    startedAt: z.string().datetime(),
    finishedAt: z.string().datetime(),
    commit: z.string().regex(/^[a-f0-9]{7,40}$/).optional(),
  }).strict(),
  /** Deterministic methods spend nothing on models; a run that did is not this kind of evidence. */
  modelCalls: z.literal(0),
  /** Additive: historic R01 evidence keeps its original fingerprint. */
  compiledManifest: z.object({
    manifestHash: sha256Schema,
    compilerHash: sha256Schema,
    componentHashes: z.array(sha256Schema).min(1),
  }).strict().optional(),
  cases: z.array(deterministicMethodRunCaseSchema).min(1),
  result: z.enum(["pass", "fail"]),
  /** sha256 of the reproducible part of the record: everything except when it was executed. */
  evidenceFingerprint: sha256Schema,
  notes: z.string().max(4000).default(""),
}).strict();
export type DeterministicMethodRun = z.infer<typeof deterministicMethodRunSchema>;

/** The part of a run that must reproduce exactly. Timestamps and commit are deliberately outside. */
export function deterministicRunEvidence(record: Pick<DeterministicMethodRun, "runId" | "kind" | "method" | "executor" | "harness" | "modelCalls" | "cases" | "result" | "compiledManifest">) {
  return {
    runId: record.runId,
    kind: record.kind,
    method: record.method,
    executor: record.executor,
    harness: record.harness,
    modelCalls: record.modelCalls,
    cases: record.cases,
    result: record.result,
    ...(record.compiledManifest ? {compiledManifest: record.compiledManifest} : {}),
  };
}

export function deterministicRunEvidenceFingerprint(record: Parameters<typeof deterministicRunEvidence>[0]): string {
  return createHash("sha256").update(stableJson(deterministicRunEvidence(record))).digest("hex");
}

/** The verdict a rung can rely on: every case passed, executed, with no model in the loop. */
export function runCountsForPromotion(record: DeterministicMethodRun): boolean {
  return record.result === "pass"
    && record.modelCalls === 0
    && record.cases.length > 0
    && record.cases.every((entry) => entry.passed)
    && deterministicRunEvidenceFingerprint(record) === record.evidenceFingerprint;
}

/** Reads `<runsRoot>/<runId>/run.json`. Directories without one are model-review runs, not these. */
export function loadDeterministicMethodRuns(runsRoot: string): Map<string, DeterministicMethodRun> {
  const records = new Map<string, DeterministicMethodRun>();
  let entries: string[] = [];
  try {
    entries = readdirSync(runsRoot, {withFileTypes: true}).filter((entry) => entry.isDirectory()).map((entry) => entry.name).sort();
  } catch {
    return records;
  }
  for (const name of entries) {
    let text: string;
    try {
      text = readFileSync(join(runsRoot, name, "run.json"), "utf8");
    } catch {
      continue;
    }
    const record = deterministicMethodRunSchema.parse(JSON.parse(text));
    if (record.runId !== name) throw new Error(`deterministic run ${name} does not match its runId ${record.runId}`);
    records.set(record.runId, record);
  }
  return records;
}

function stableJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(stableJson).join(",")}]`;
  if (value !== null && typeof value === "object") {
    const record = value as Record<string, unknown>;
    return `{${Object.keys(record).sort().map((key) => `${JSON.stringify(key)}:${stableJson(record[key])}`).join(",")}}`;
  }
  return JSON.stringify(value) ?? "null";
}

packages/financial-core/src/capital-peri.content:
import Decimal from "decimal.js";
import {buildOperatingCashProjection, type OperatingCashProjectionInput} from "./operating-cash-projection";
import {buildFinancingCashFlows, type FinancingCostsInput} from "./financing-costs";

const Exact = Decimal.clone({precision: 100, rounding: Decimal.ROUND_HALF_UP});
export const capitalPeriodCashVersion = "2026.09.20-v1";
export type CapitalMovement = {
  id: string; economicId: string; date: string; amount: string;
  account: "available" | "restricted";
  kind: "equity_contribution" | "distribution" | "asset_sale" | "acquisition";
  reason: string;
};
export type CapitalPeriodCashInput = {
  capitalMovements: readonly CapitalMovement[];
  capitalMovementInventory: {status: "declared_complete" | "unknown"; reason: string};
  operating: OperatingCashProjectionInput;
  financing: {status: "provided"; input: FinancingCostsInput} | {status: "no_debt_or_financing"; reason: string};
  openingAvailable: string | null; openingRestricted: string | null;
  /** Requires upstream adoption. Restricted operating movements need a different budget. */
  operatingCashAccount: "available";
};
function opening(value: string | null, signed: boolean) {
  if (value === null) return null;
  if (typeof value !== "string" || !(signed ? /^-?\d{1,24}(?:\.\d{1,8})?$/ : /^\d{1,24}(?:\.\d{1,8})?$/).test(value)) throw new Error("capital_period_cash_invalid_opening");
  return new Exact(value);
}

/** Recomputes both component engines; never accepts a precomputed financial result. Period
 * closing balances do not establish daily or intraday liquidity. A longer residual debt
 * remains visible instead of being treated as a lower lifetime financing cost. */
export function buildCapitalPeriodCash(input: CapitalPeriodCashInput) {
  if (input.operatingCashAccount !== "available") throw new Error("capital_period_cash_operating_account_required");
  const op = buildOperatingCashProjection(input.operating);
  let cash = opening(input.openingAvailable, true); let restricted = opening(input.openingRestricted, false);
  if (!input.financing || !["provided", "no_debt_or_financing"].includes(input.financing.status)) throw new Error("capital_period_cash_financing_inventory_required");
  if (input.financing.status === "no_debt_or_financing" && (typeof input.financing.reason !== "string" || !input.financing.reason.trim())) throw new Error("capital_period_cash_no_debt_reason_required");
  if (input.financing.status === "provided") {
    const d = input.financing.input.debt;
    if (d.currency !== op.currency || d.openingDate !== op.openingDate || d.endDate !== op.endDate) throw new Error("capital_period_cash_context_mismatch");
  }
  const financing = input.financing.status === "provided" ? buildFinancingCashFlows(input.financing.input) : null;
  if (!input.capitalMovementInventory || !["declared_complete", "unknown"].includes(input.capitalMovementInventory.status)
    || typeof input.capitalMovementInventory.reason !== "string" || !input.capitalMovementInventory.reason.trim()
    || !Array.isArray(input.capitalMovements) || input.capitalMovements.length > 2000) throw new Error("capital_period_cash_movement_inventory_required");
  const ids = new Set<string>(); const economics = new Set<string>(financing?.charges.map(c => c.economicId) ?? []);
  const movements = input.capitalMovements.map(m => {
    if (typeof m.id !== "string" || !m.id.trim() || ids.has(m.id) || typeof m.economicId !== "string" || !m.economicId.trim()
      || economics.has(m.economicId)) throw new Error("capital_period_cash_duplicate_movement");
    ids.add(m.id); economics.add(m.economicId);
    const date = new Date(`${m.date}T00:00:00Z`);
    if (!/^[1-9]\d{3}-\d{2}-\d{2}$/.test(m.date) || !Number.isFinite(date.getTime()) || date.toISOString().slice(0, 10) !== m.date
      || m.date <= op.openingDate || m.date > op.endDate) throw new Error("capital_period_cash_movement_date");
    if (!["equity_contribution", "distribution", "asset_sale", "acquisition"].includes(m.kind)
      || !["available", "restricted"].includes(m.account) || typeof m.reason !== "string" || !m.reason.trim()) throw new Error("capital_period_cash_movement_definition");
    const amount = opening(m.amount, false);
    if (amount === null) throw new Error("capital_period_cash_movement_amount_required");
    return {...m, amount: amount.toFixed(), direction: ["equity_contribution", "asset_sale"].includes(m.kind) ? "inflow" as const : "outflow" as const};
  });
  const common = {schemaVersion: "capital-period-cash.v1" as const, engineVersion: capitalPeriodCashVersion,
    operands: structuredClone(input), operating: op, financing, capitalMovements: movements,
    measurement: "opening_and_period_end_balances" as const,
    exclusions: ["intraperiod_liquidity", "lifetime_cost_when_residual_debt_exists", "contractual_covenant_certification", "source_completeness"] as const};
  const gaps: string[] = [];
  if (input.capitalMovementInventory.status === "unknown") gaps.push("capital_movements_unknown");
  if (cash === null) gaps.push("opening_available_unknown");
  if (restricted === null) gaps.push("opening_restricted_unknown");
  if (financing?.status === "missing_inputs") gaps.push("financing_costs_unknown");
  if (gaps.length) return {...common, status: "missing_inputs" as const, rows: null, summary: null, gaps};
  let minimumAvailable = cash!; let minimumRestricted = restricted!;
  const events = financing?.events ?? [];
  const rows = op.rows.map(period => {
    const selected = events.filter(e => e.date >= period.startDate && e.date <= period.endDate);
    const net = (account: "available" | "restricted") => selected.filter(e => e.account === account)
      .reduce((sum, e) => sum.plus(new Exact(e.amount!).times(e.direction === "inflow" ? 1 : -1)), new Exact(0));
    const availableFinance = net("available"); const restrictedFinance = net("restricted");
    const capital = movements.filter(m => m.date >= period.startDate && m.date <= period.endDate);
    const capitalNet = (account: "available" | "restricted") => capital.filter(m => m.account === account)
      .reduce((n, m) => n.plus(new Exact(m.amount).times(m.direction === "inflow" ? 1 : -1)), new Exact(0));
    const availableCapital = capitalNet("available"); const restrictedCapital = capitalNet("restricted");
    const openingAvailable = cash!; const openingRestricted = restricted!;
    cash = cash!.plus(period.cashBeforeFinancing).plus(availableFinance).plus(availableCapital);
    restricted = restricted!.plus(restrictedFinance).plus(restrictedCapital);
    minimumAvailable = Exact.min(minimumAvailable, cash); minimumRestricted = Exact.min(minimumRestricted, restricted);
    const debts = (financing?.debt ?? []).map(instrument => {
      const row = instrument.rows.find(r => r.endDate === period.endDate);
      if (!row) throw new Error("capital_period_cash_debt_stock_date_missing");
      return {instrumentId: instrument.instrumentId, closingPrincipal: row.closingPrincipal};
    });
    const closingDebt = debts.reduce((n, d) => n.plus(d.closingPrincipal), new Exact(0));
    return {periodId: period.periodId, startDate: period.startDate, endDate: period.endDate,
      openingAvailable: openingAvailable.toFixed(), openingRestricted: openingRestricted.toFixed(),
      cashBeforeFinancing: period.cashBeforeFinancing, netFinancingAvailable: availableFinance.toFixed(),
      netFinancingRestricted: restrictedFinance.toFixed(), netCapitalAvailable: availableCapital.toFixed(), netCapitalRestricted: restrictedCapital.toFixed(), capitalMovementIds: capital.map(m => m.id), closingAvailable: cash.toFixed(), closingRestricted: restricted.toFixed(),
      availableShortfallAtPeriodEnd: Exact.max(cash.negated(), 0).toFixed(), restrictedShortfallAtPeriodEnd: Exact.max(restricted.negated(), 0).toFixed(),
      closingDebt: closingDebt.toFixed(), instrumentStocks: debts, financingEventIds: selected.map(e => e.id)};
  });
  return {...common, status: "calculated" as const, rows, gaps,
    summary: {closingAvailable: cash!.toFixed(), closingRestricted: restricted!.toFixed(),
      minimumAvailableAtMeasuredDates: minimumAvailable.toFixed(), maximumAvailableShortfallAtMeasuredDates: Exact.max(minimumAvailable.negated(), 0).toFixed(),
      minimumRestrictedAtMeasuredDates: minimumRestricted.toFixed(), maximumRestrictedShortfallAtMeasuredDates: Exact.max(minimumRestricted.negated(), 0).toFixed(),
      closingDebt: rows.at(-1)!.closingDebt, nominalFinancingCostInHorizon: financing?.totals?.nominalFinancingCostInHorizon ?? "0",
      lifetimeCostCompared: false as const, intraperiodLiquidityVerified: false as const}};
}

