packages/financial-core/src/material-ari.content:
import Decimal from "decimal.js";

import type {CalculationTrace} from "./credit-math";
import {finiteFigure, fullFigure, parseFigure} from "./figure-input";

/**
 * The arithmetic of the governed credit materials (stage 19, increments 6, 6B and 6C).
 *
 * `@offroad/case-materials` assembles the documents a company takes to market; every number it
 * prints that is not a value it received (a sum, a difference, a share, a tolerance test, a unit or
 * precision conversion) is computed here, in Decimal, with a trace naming the formula and the
 * operands. The operation verdict of `@offroad/credit-analysis`, which the credit memo carries,
 * computes and prints through the same kernels, and so do the price sentences of
 * `@offroad/market-reference`. Two kinds of kernel live in this file:
 *
 * - computations, which create a financial figure (the new instrument's amount, the concentration
 *   of the leading customers, the EBITDA adjustments, the tie-out of the debt schedule, the
 *   difference between two spreads, and for the verdict the net new money, the enlarged ticket,
 *   the leverage after a structure, the covenant ceiling test and the heaviest schedule year); and
 * - presentation conversions, which print a figure in another unit or at a stated precision
 *   (percent, millions, basis points as percent, a signed spread, an amount by the one rule every
 *   material prints amounts with, a ratio as the desk publishes it, half-up rounding) and, at the
 *   very edge, hand an exact decimal to the binary number that `Intl.NumberFormat` and a chart
 *   point require.
 *
 * Figures are full-precision decimal strings (`Decimal#toFixed()` without rounding) unless the
 * kernel is a rounding one. A value that is not a finite decimal number is refused, never read as
 * zero.
 */
export const materialArithmeticVersion = "2026.09.27-v5";

// The same arithmetic contract the package root declares, so a kernel imported on its own computes
// exactly what it computes inside a published material.
Decimal.set({precision: 40, rounding: Decimal.ROUND_HALF_UP, toExpNeg: -30, toExpPos: 30});

export type MaterialFigure = {readonly value: string; readonly trace: CalculationTrace};

const parse = parseFigure;
const finite = finiteFigure;
const full = fullFigure;

// Computations ---------------------------------------------------------------------------------

/**
 * The amount of the new instrument in a liability-management structure: the balance of the
 * covenanted lines it takes out plus the net new money for the company's plan. Sources equal uses by
 * construction, which is why the sources-and-uses table states it once.
 */
export function calculateNewInstrumentAmount(input: {covenantedBalance: Decimal.Value; netNewMoney: Decimal.Value}): MaterialFigure {
  const takeout = finite("covenanted balance", input.covenantedBalance);
  const newMoney = finite("net new money", input.netNewMoney);
  const amount = takeout.plus(newMoney);
  return {
    value: full(amount),
    trace: {
      id: "material.new_instrument_amount",
      formula: "new instrument = covenanted balance taken out + net new money",
      operands: {covenantedBalance: full(takeout), netNewMoney: full(newMoney)},
      result: full(amount),
    },
  };
}

export type CustomerConcentration = {
  /** Sum of the first `leading` shares in the order the source ranks them. */
  readonly leadingTotal: string;
  /** The largest share; among equal shares, the first one listed. Null for an empty list. */
  readonly largest: {readonly id: string; readonly share: string} | null;
  /** Every id, largest share first; equal shares keep the order the source lists them in. */
  readonly ranking: readonly string[];
  readonly trace: CalculationTrace;
};

/**
 * Customer concentration as a diligence answer states it: the share of the leading customers,
 * summed in the ranking the source declares (customer 1 is the source's largest), and the largest
 * single share, compared exactly. The ranking by share is stable, so a tie never reorders the
 * customers the source listed first.
 */
export function calculateCustomerConcentration(input: {shares: ReadonlyArray<{id: string; share: Decimal.Value}>; leading: number}): CustomerConcentration {
  if (!Number.isInteger(input.leading) || input.leading < 1) throw new RangeError("leading count must be a positive integer");
  const shares = input.shares.map((entry) => ({id: entry.id, share: finite(`share of ${entry.id}`, entry.share)}));
  const leadingTotal = shares.slice(0, input.leading).reduce((sum, entry) => sum.plus(entry.share), new Decimal(0));
  const ranked = shares.map((entry, index) => ({...entry, index}))
    .sort((a, b) => b.share.comparedTo(a.share) || a.index - b.index);
  const largest = ranked[0] ? {id: ranked[0].id, share: full(ranked[0].share)} : null;
  return {
    leadingTotal: full(leadingTotal),
    largest,
    ranking: ranked.map((entry) => entry.id),
    trace: {
      id: "material.customer_concentration",
      formula: "leading total = sum of the first N shares in the declared ranking; largest = maximum share, the first listed among equals",
      operands: {leading: String(input.leading), ...Object.fromEntries(shares.map((entry) => [entry.id, full(entry.share)]))},
      result: `leadingTotal=${full(leadingTotal)}; largest=${largest ? `${largest.id}:${largest.share}` : "none"}`,
    },
  };
}

/** Adjustments between reported and adjusted EBITDA: the signed difference and its magnitude. */
export function calculateEbitdaAdjustments(input: {adjustedEbitda: Decimal.Value; reportedEbitda: Decimal.Value}): MaterialFigure & {readonly magnitude: string} {
  const adjusted = finite("adjusted EBITDA", input.adjustedEbitda);
  const reported = finite("reported EBITDA", input.reportedEbitda);
  const difference = adjusted.minus(reported);
  return {
    value: full(difference),
    magnitude: full(difference.abs()),
    trace: {
      id: "material.ebitda_adjustments",
      formula: "adjustments = adjusted EBITDA - reported EBITDA; magnitude = |adjustments|",
      operands: {adjustedEbitda: full(adjusted), reportedEbitda: full(reported)},
      result: full(difference),
    },
  };
}

export type ScheduleTieOut = {
  readonly outcome: "within_tolerance" | "outside_tolerance";
  /** |balance - schedule|. */
  readonly magnitude: string;
  /** tolerance x total debt on the balance sheet. */
  readonly limit: string;
  /** Which side carries the difference: debt on the balance sheet that the schedule misses, or the reverse. */
  readonly side: "balance_above_schedule" | "schedule_above_balance";
  readonly trace: CalculationTrace;
};

/**
 * Whether the debt schedule ties to the balance sheet: the gap (balance minus schedule) is within
 * the tolerance when its magnitude does not exceed the tolerance times the debt on the balance
 * sheet. A gap exactly at the limit is within it.
 */
export function testScheduleTieOut(input: {scheduleGap: Decimal.Value; totalOnBalance: Decimal.Value; tolerance: Decimal.Value}): ScheduleTieOut {
  const gap = finite("schedule gap", input.scheduleGap);
  const balance = finite("debt on the balance sheet", input.totalOnBalance);
  const tolerance = finite("tolerance", input.tolerance);
  if (tolerance.isNegative()) throw new RangeError("tolerance must not be negative");
  const limit = balance.times(tolerance);
  const within = gap.abs().lte(limit);
  return {
    outcome: within ? "within_tolerance" : "outside_tolerance",
    magnitude: full(gap.abs()),
    limit: full(limit),
    side: gap.gt(0) ? "balance_above_schedule" : "schedule_above_balance",
    trace: {
      id: "material.schedule_tie_out",
      formula: "within when |balance - schedule| <= tolerance x debt on the balance sheet",
      operands: {scheduleGap: full(gap), totalOnBalance: full(balance), tolerance: full(tolerance)},
      result: within ? "within_tolerance" : "outside_tolerance",
    },
  };
}

/**
 * The part of a ticket that is new money: the ticket less the existing debt it redeems at
 * disbursement. Negative when the refinancing stated exceeds the ticket, so the verdict can see it.
 */
export function calculateNetNewMoney(input: {ticket: Decimal.Value; refinancing: Decimal.Value}): MaterialFigure {
  const ticket = finite("ticket", input.ticket);
  const refinancing = finite("refinancing", input.refinancing);
  const netNewMoney = ticket.minus(refinancing);
  return {
    value: full(netNewMoney),
    trace: {
      id: "material.net_new_money",
      formula: "net new money = ticket - existing debt redeemed at disbursement",
      operands: {ticket: full(ticket), refinancing: full(refinancing)},
      result: full(netNewMoney),
    },
  };
}

/**
 * The ticket the verdict offers as the second road: large enough to clear one more year of the
 * schedule, so the ticket and the debt it redeems both grow by that year's principal.
 */
export function calculateEnlargedTicket(input: {ticket: Decimal.Value; refinancing: Decimal.Value; principalDue: Decimal.Value}): {
  readonly ticket: string;
  readonly refinancing: string;
  readonly trace: CalculationTrace;
} {
  const ticket = finite("ticket", input.ticket);
  const refinancing = finite("refinancing", input.refinancing);
  const principalDue = finite("principal due", input.principalDue);
  const enlarged = ticket.plus(principalDue);
  const redeemed = refinancing.plus(principalDue);
  return {
    ticket: full(enlarged),
    refinancing: full(redeemed),
    trace: {
      id: "material.enlarged_ticket",
      formula: "enlarged ticket = ticket + principal due; enlarged refinancing = refinancing + principal due",
      operands: {ticket: full(ticket), refinancing: full(refinancing), principalDue: full(principalDue)},
      result: `ticket=${full(enlarged)}; refinancing=${full(redeemed)}`,
    },
  };
}

/**
 * Net leverage once a structure lands: the net debt today plus the part of the ticket that does not
 * redeem existing debt, over EBITDA, rounded half-up to `decimals` places when a precision is stated.
 * Over a zero EBITDA the ratio is not a number and the value is null: never an infinite leverage
 * handed on as if it were one.
 */
export function calculateLeverageAfterStructure(input: {netDebt: Decimal.Value; ticket: Decimal.Value; redeemed: Decimal.Value; ebitda: Decimal.Value; decimals?: number}): {
  readonly value: string | null;
  readonly trace: CalculationTrace;
} {
  if (input.decimals !== undefined && (!Number.isInteger(input.decimals) || input.decimals < 0 || input.decimals > 20)) {
    throw new RangeError("decimals must be an integer between 0 and 20");
  }
  const netDebt = finite("net debt", input.netDebt);
  const ticket = finite("ticket", input.ticket);
  const redeemed = finite("redeemed debt", input.redeemed);
  const ebitda = finite("EBITDA", input.ebitda);
  const operands = {netDebt: full(netDebt), ticket: full(ticket), redeemed: full(redeemed), ebitda: full(ebitda)};
  const formula = `leverage = (net debt + ticket - redeemed) / EBITDA${input.decimals === undefined ? "" : `, half-up to ${input.decimals} decimals`}`;
  if (ebitda.isZero()) return {value: null, trace: {id: "material.leverage_after_structure", formula, operands, result: "not computable: zero EBITDA"}};
  const leverage = netDebt.plus(ticket.minus(redeemed)).div(ebitda);
  const value = input.decimals === undefined ? full(leverage) : leverage.toFixed(input.decimals, Decimal.ROUND_HALF_UP);
  return {value, trace: {id: "material.leverage_after_structure", formula, operands, result: value}};
}

/**
 * The first test of the verdict: whether leverage today sits above the tightest covenant's ceiling,
 * and by how much. A leverage that is absent or not a finite number (the ratio over a zero EBITDA)
 * is not computable and is never compared with a ceiling.
 */
export function testCovenantCeiling(input: {leverage: Decimal.Value | null; ceiling: Decimal.Value}): {
  readonly outcome: "above_ceiling" | "within_ceiling" | "not_computable";
  /** Leverage minus the ceiling, when above it. */
  readonly excess: string | null;
  readonly trace: CalculationTrace;
} {
  const ceiling = finite("covenant ceiling", input.ceiling);
  const leverage = input.leverage === null ? null : parse(input.leverage);
  const trace = (result: string) => ({
    id: "material.covenant_ceiling",
    formula: "above when leverage > ceiling; excess = leverage - ceiling",
    operands: {leverage: leverage ? full(leverage) : input.leverage === null ? "absent" : String(input.leverage), ceiling: full(ceiling)},
    result,
  });
  if (!leverage) return {outcome: "not_computable", excess: null, trace: trace("not computable: leverage is not a finite number")};
  if (!leverage.gt(ceiling)) return {outcome: "within_ceiling", excess: null, trace: trace("within_ceiling")};
  const excess = full(leverage.minus(ceiling));
  return {outcome: "above_ceiling", excess, trace: trace(`above_ceiling; excess=${excess}`)};
}

/**
 * The heaviest year of an amortisation schedule: the largest strain (principal due over the year's
 * EBITDA) above the threshold, the first listed among equals. Strains compare exactly, never as
 * binary numbers. A strain that is absent or not a finite number (the principal over a zero projected
 * EBITDA) cannot be ranked and is left out, named in the trace.
 */
export function selectHeaviestScheduleYear(input: {years: ReadonlyArray<{id: string; strain: Decimal.Value | null}>; threshold: Decimal.Value}): {
  readonly id: string | null;
  readonly strain: string | null;
  readonly trace: CalculationTrace;
} {
  const threshold = finite("strain threshold", input.threshold);
  const parse = (value: Decimal.Value | null) => (value === null ? null : parseFigure(value));
  const unranked = input.years.filter((year) => !parse(year.strain)).map((year) => year.id);
  let heaviest: {id: string; strain: Decimal} | null = null;
  for (const year of input.years) {
    const strain = parse(year.strain);
    if (!strain || !strain.gt(threshold)) continue;
    if (!heaviest || strain.gt(heaviest.strain)) heaviest = {id: year.id, strain};
  }
  return {
    id: heaviest?.id ?? null,
    strain: heaviest ? full(heaviest.strain) : null,
    trace: {
      id: "material.heaviest_schedule_year",
      formula: "heaviest = largest strain above the threshold, the first listed among equals; a strain that is not a finite number is not ranked",
      operands: {threshold: full(threshold), ...Object.fromEntries(input.years.map((year) => [year.id, parse(year.strain) ? full(parse(year.strain)!) : year.strain === null ? "absent" : String(year.strain)]))},
      result: `${heaviest ? `${heaviest.id}:${full(heaviest.strain)}` : "none"}${unranked.length ? `; not ranked: ${unranked.join(", ")}` : ""}`,
    },
  };
}

/**
 * Compares two figures exactly, for the thresholds a document's decisions test (a coverage under
 * 1.3x, a refinancing below the wall). A comparison creates no figure, so it carries no trace; it
 * exists so that a decision never compares binary numbers. Refuses a value that is not a finite
 * decimal number.
 */
export function compareFigures(left: Decimal.Value, right: Decimal.Value): -1 | 0 | 1 {
  return finite("left figure", left).comparedTo(finite("right figure", right)) as -1 | 0 | 1;
}

/**
 * How far one spread sits from another, both in basis points, as the verdict compares an
 * alternative's price with the requested structure's: the signed difference, in basis points.
 * Fractional basis points subtract exactly (372.3 - 370.1 is 2.2).
 */
export function calculateSpreadDifference(input: {spreadBps: Decimal.Value; referenceBps: Decimal.Value}): MaterialFigure {
  const spread = finite("spread in basis points", input.spreadBps);
  const reference = finite("reference spread in basis points", input.referenceBps);
  const difference = spread.minus(reference);
  return {
    value: full(difference),
    trace: {
      id: "material.spread_difference",
      formula: "difference = spread - reference spread, in basis points",
      operands: {spreadBps: full(spread), referenceBps: full(reference)},
      result: full(difference),
    },
  };
}

// Presentation conversions ---------------------------------------------------------------------

export type PresentationScale = "unit" | "percent" | "millions" | "basis_points_as_percent";

const scales: Record<PresentationScale, {apply: (value: Decimal) => Decimal; formula: string}> = {
  unit: {apply: (value) => value, formula: "value"},
  percent: {apply: (value) => value.times(100), formula: "value x 100"},
  millions: {apply: (value) => value.div(1_000_000), formula: "value / 1,000,000"},
  basis_points_as_percent: {apply: (value) => value.div(100), formula: "basis points / 100"},
};

/**
 * A figure in the unit and at the precision a document prints it: scaled exactly, then rounded half
 * away from zero to `decimals` places when a precision is stated. Rounding is on the decimal value,
 * so a figure that sits exactly on a tie (1.005 to two places) rounds up, as the reader expects.
 */
export function presentationFigure(input: {value: Decimal.Value; scale?: PresentationScale; decimals?: number}): MaterialFigure {
  const scale = input.scale ?? "unit";
  if (input.decimals !== undefined && (!Number.isInteger(input.decimals) || input.decimals < 0 || input.decimals > 20)) {
    throw new RangeError("decimals must be an integer between 0 and 20");
  }
  const value = finite("presentation value", input.value);
  const scaled = scales[scale].apply(value);
  const printed = input.decimals === undefined ? full(scaled) : scaled.toFixed(input.decimals, Decimal.ROUND_HALF_UP);
  return {
    value: printed,
    trace: {
      id: "material.presentation_figure",
      formula: input.decimals === undefined ? scales[scale].formula : `${scales[scale].formula}, half-up to ${input.decimals} decimals`,
      operands: {value: full(value), scale},
      result: printed,
    },
  };
}

/**
 * A ratio at the precision the desk publishes it. A finite ratio prints exactly as
 * `presentationFigure` prints it. A ratio over a zero denominator is absent (stage 19, second
 * polish): null stays null, and the text a division by zero printed before (`Infinity`,
 * `-Infinity`, `NaN`, as a desk stored until then publishes it) is read as absent too, so it is
 * never printed, compared or read as zero. Any other text that is not a decimal number is refused.
 */
export function presentationRatio(input: {value: string | null; decimals: number}): {readonly value: string | null; readonly trace: CalculationTrace} {
  if (input.value === null || /^(?:-?Infinity|NaN)$/.test(input.value)) {
    const stated = input.value ?? "absent";
    return {value: null, trace: {id: "material.presentation_ratio", formula: "a ratio over a zero denominator is absent", operands: {value: stated}, result: "absent"}};
  }
  const figure = presentationFigure({value: input.value, decimals: input.decimals});
  return {value: figure.value, trace: {...figure.trace, id: "material.presentation_ratio"}};
}

export type AmountLocale = "pt-BR" | "en-US";

export type PresentationAmount = {
  /** The amount as a document prints it: "R$ 17,4M", "R$ 45 mil", "R$ 45 thousand", "R$ 42.300.000". */
  readonly text: string;
  /** The printed figure as a decimal string, before the separators of the locale. */
  readonly figure: string;
  readonly unit: "millions" | "thousands" | "units";
  readonly trace: CalculationTrace;
};

// From here, thousands without decimals would print 1,000 thousand: the amount is stated in millions.
const MILLIONS_FROM = new Decimal("999500");

/**
 * The one rule by which every material prints an amount, so that no amount that is not zero ever
 * prints as zero. Two styles:
 *
 * - `abbreviated`, for amounts in a sentence: millions with one decimal from R$ 999,500 (where
 *   thousands would round to a thousand thousand), "R$ 17,4M" and "R$ 17.4M"; thousands without
 *   decimals from R$ 1 thousand, "R$ 45 mil" and "R$ 45 thousand"; below that, the exact amount in
 *   units, "R$ 450".
 * - `whole`, for amounts in a table or a term: whole units grouped as the locale groups them,
 *   "R$ 42.300.000" and "R$ 42,300,000"; an amount under one unit that is not zero, exact, "R$ 0,3".
 *
 * Rounding is half away from zero on the decimal value; zero prints as zero, "R$ 0".
 */
export function presentationAmount(input: {value: Decimal.Value; locale: AmountLocale; style: "abbreviated" | "whole"; currency?: string}): PresentationAmount {
  const value = finite("amount", input.value);
  const currency = input.currency ?? "R$";
  const separator = input.locale === "pt-BR" ? "," : ".";
  const local = (figure: string) => figure.replace(".", separator);
  const magnitude = value.abs();
  let unit: PresentationAmount["unit"];
  let figure: string;
  let text: string;
  if (input.style === "abbreviated" && magnitude.gte(MILLIONS_FROM)) {
    unit = "millions";
    figure = value.div(1_000_000).toFixed(1, Decimal.ROUND_HALF_UP);
    text = `${currency} ${local(figure)}M`;
  } else if (input.style === "abbreviated" && magnitude.gte(1000)) {
    unit = "thousands";
    figure = value.div(1000).toFixed(0, Decimal.ROUND_HALF_UP);
    text = `${currency} ${figure} ${input.locale === "pt-BR" ? "mil" : "thousand"}`;
  } else if (input.style === "whole" && (magnitude.gte(1) || value.isZero())) {
    unit = "units";
    figure = value.toFixed(0, Decimal.ROUND_HALF_UP);
    // The figure is already a whole number; Intl only groups its digits in the locale.
    text = `${currency} ${presentationNumber(figure).value.toLocaleString(input.locale, {maximumFractionDigits: 0})}`;
  } else {
    unit = "units";
    figure = full(value);
    text = `${currency} ${local(figure)}`;
  }
  return {
    text,
    figure,
    unit,
    trace: {
      id: "material.presentation_amount",
      formula: input.style === "abbreviated"
        ? "millions, half-up to 1 decimal, from 999500; thousands, half-up to 0 decimals, from 1000; below, the exact amount"
        : "whole units, half-up; below one unit and not zero, the exact amount",
      operands: {value: full(value), style: input.style, locale: input.locale},
      result: text,
    },
  };
}

/**
 * A spread in basis points as the signed percentage a price sentence states ("CDI + 2.5%",
 * "CDI - 1%"): the sign apart from the magnitude, which is exact, or rounded half-up to `decimals`
 * places when a precision is stated. Zero carries the plus sign, as a sentence writes "CDI + 0%".
 */
export function presentationSpread(input: {bps: Decimal.Value; decimals?: number}): {readonly sign: "+" | "-"; readonly magnitude: string; readonly trace: CalculationTrace} {
  const bps = finite("spread in basis points", input.bps);
  const magnitude = presentationFigure({value: bps.abs(), scale: "basis_points_as_percent", ...(input.decimals === undefined ? {} : {decimals: input.decimals})}).value;
  const sign = bps.isNegative() && !bps.isZero() ? "-" : "+";
  return {
    sign,
    magnitude,
    trace: {
      id: "material.presentation_spread",
      formula: `sign of the spread; |basis points| / 100${input.decimals === undefined ? "" : `, half-up to ${input.decimals} decimals`}`,
      operands: {bps: full(bps)},
      result: `${sign}${magnitude}`,
    },
  };
}

/**
 * The exact decimal handed to the binary number `Intl.NumberFormat` prints and a native chart point
 * stores. This is the only floating-point step of a material, at the display boundary, and it reads
 * the decimal exactly as `Number` reads decimal text.
 */
export function presentationNumber(value: Decimal.Value): {readonly value: number; readonly trace: CalculationTrace} {
  const parsed = finite("presentation number", value);
  const number = parsed.toNumber();
  return {value: number, trace: {id: "material.presentation_number", formula: "nearest binary64 number to the decimal", operands: {value: full(parsed)}, result: String(number)}};
}

/** The same conversion for a value that may be text: null when it is not a finite decimal number, so the caller prints it as written. */
export function tryPresentationNumber(value: Decimal.Value): {readonly value: number; readonly trace: CalculationTrace} | null {
  return parse(value) ? presentationNumber(value) : null;
}

packages/financial-core/src/desk-arithme.content:
import Decimal from "decimal.js";

import type {CalculationTrace} from "./credit-math";
import {finiteFigure as finite, fullFigure as full} from "./figure-input";

/**
 * The arithmetic of the desk battery and of the leverage trajectory (stage 19, post-closure polish).
 *
 * `@offroad/credit-analysis` reads a company the way a head of credit does before writing a sentence:
 * the stack on one axis, leverage before and after the ask against the tightest covenant, interest
 * coverage, the runway of a company that burns cash, the cash cycle and what growth absorbs, the
 * receivables still free, and the trajectory of leverage year by year with the covenant a new
 * instrument would carry. Every figure of that reading is computed here, in Decimal at 40
 * significant digits with half-up rounding, with a trace naming the formula and the operands; the
 * package keeps the calendar (months between two dates), the text it reads and the sentences.
 *
 * Figures are full-precision decimal strings unless the kernel states the precision the desk
 * publishes. A value received that is not a finite decimal number is refused, never read as zero.
 *
 * A ratio over a zero denominator is absent (stage 19, second polish): the kernel hands it on as
 * null, lists it in `absent` with the denominator that is zero, names it in the trace, and never
 * compares it with a threshold or with another ratio. Until then the desk published such a ratio as
 * a division by zero prints it (`Infinity`, `-Infinity`, `NaN`). A ratio over a negative
 * denominator is a number and is handed on as before.
 */
export const deskArithmeticVersion = "2026.09.27-v3";

// The same arithmetic contract the package root declares, so a kernel imported on its own computes
// exactly what it computes inside the desk.
Decimal.set({precision: 40, rounding: Decimal.ROUND_HALF_UP, toExpNeg: -30, toExpPos: 30});

const ZERO = new Decimal(0);

/**
 * A ratio a kernel could not compute because its denominator is zero: the output it would fill
 * (`preTurns`, `scenarios.2.postTurns`, `2027.leverageBase`) and the denominator, named.
 */
export type AbsentRatio = {readonly ratio: string; readonly denominator: string};

/** The quotient, or null when the denominator is zero: an absent ratio, never a number. */
const quotient = (numerator: Decimal, denominator: Decimal): Decimal | null => (denominator.isZero() ? null : numerator.div(denominator));
/** How a trace states a ratio that may be absent. */
const traced = (value: Decimal | string | null, denominator: string) =>
  value === null ? `absent (zero ${denominator})` : typeof value === "string" ? value : full(value);

// The stack on one axis -------------------------------------------------------------------------

export type DeskStackLine = {
  balance: Decimal.Value;
  /** Effective annual cost on the common axis; null when the line could not be priced. */
  effectiveAnnual: Decimal.Value | null;
  /** Calendar months from the reference date to the line's maturity; null when the line states none. */
  monthsToMaturity: number | null;
};

/** A window of a maturity profile ("Jun/26 a Mai/27: 1.229.828"): the principal and the months to its end, when it has one. */
export type DeskMaturityWindow = {amount: Decimal.Value; monthsToEnd: number | null};

export type DeskDebtStack = {
  /** Each line's balance at cents, the axis the stack is summed on. */
  readonly lineBalances: readonly string[];
  readonly totalSchedule: string;
  readonly totalOnBalance: string;
  /** Balance sheet less the schedule: positive when the balance sheet recognises debt the schedule does not list. */
  readonly scheduleGap: string;
  /** Balance-weighted effective annual cost of the lines that could be priced; null when none could. */
  readonly weightedCost: string | null;
  readonly maturingWithin24Months: string;
  readonly maturingWithin12Months: string;
  /** Cash over the principal due within 12 months; null when nothing is due. */
  readonly liquidityCoverage12: string | null;
  /** Principal due within 24 months over the schedule, capped at the whole schedule; null unless both are positive. */
  readonly maturingShare24: string | null;
  readonly trace: CalculationTrace;
};

/**
 * The stack on one axis: each line at cents, the schedule against the balance sheet, the
 * balance-weighted cost of what can be priced, and the principal falling due within 12 and 24
 * months. A line without a maturity is not a line that never matures: when some lines state no
 * date and the maturity profile of the notes says more falls due in the window, the profile wins.
 */
export function calculateDeskDebtStack(input: {
  lines: readonly DeskStackLine[];
  grossDebt: Decimal.Value;
  cash: Decimal.Value;
  maturityProfile: readonly DeskMaturityWindow[];
}): DeskDebtStack {
  const balances = input.lines.map((line, index) => new Decimal(finite(`balance of line ${index + 1}`, line.balance).toFixed(2)));
  const costs = input.lines.map((line, index) => (line.effectiveAnnual === null ? null : finite(`cost of line ${index + 1}`, line.effectiveAnnual)));
  const totalSchedule = balances.reduce((sum, balance) => sum.plus(balance), ZERO);
  const totalOnBalance = finite("gross debt on the balance sheet", input.grossDebt);
  const scheduleGap = totalOnBalance.minus(totalSchedule);
  const priceableTotal = balances.reduce((sum, balance, index) => (costs[index] === null ? sum : sum.plus(balance)), ZERO);
  const weightedCost = priceableTotal.gt(0)
    ? balances.reduce((sum, balance, index) => (costs[index] === null ? sum : sum.plus(balance.times(costs[index]!))), ZERO).div(priceableTotal)
    : null;

  const within = (months: number | null, limit: number) => months !== null && months <= limit;
  const linesWithDates = input.lines.filter((line) => line.monthsToMaturity !== null).length;
  const maturing = (limit: number) => {
    const fromLines = balances.reduce((sum, balance, index) => (within(input.lines[index]!.monthsToMaturity, limit) ? sum.plus(balance) : sum), ZERO);
    const fromProfile = input.maturityProfile.reduce(
      (sum, window, index) => (within(window.monthsToEnd, limit) ? sum.plus(finite(`window ${index + 1} of the maturity profile`, window.amount)) : sum),
      ZERO,
    );
    return linesWithDates < input.lines.length && fromProfile.gt(fromLines) ? fromProfile : fromLines;
  };
  const maturing24 = maturing(24);
  const maturing12 = maturing(12);
  const cash = finite("cash", input.cash);
  const liquidityCoverage12 = maturing12.gt(0) ? cash.div(maturing12) : null;
  const maturingShare24 = maturing24.gt(0) && totalSchedule.gt(0) ? Decimal.min(maturing24.div(totalSchedule), 1) : null;

  return {
    lineBalances: balances.map((balance) => balance.toFixed(2)),
    totalSchedule: full(totalSchedule),
    totalOnBalance: full(totalOnBalance),
    scheduleGap: full(scheduleGap),
    weightedCost: weightedCost ? full(weightedCost) : null,
    maturingWithin24Months: full(maturing24),
    maturingWithin12Months: full(maturing12),
    liquidityCoverage12: liquidityCoverage12 ? full(liquidityCoverage12) : null,
    maturingShare24: maturingShare24 ? full(maturingShare24) : null,
    trace: {
      id: "desk.debt_stack",
      formula: "schedule = sum of the line balances at cents; gap = balance sheet - schedule; weighted cost = sum(balance x cost) / sum of priced balances; "
        + "due within N months = lines maturing within N months, or the maturity profile when some lines state no date and the profile says more; "
        + "liquidity coverage = cash / due within 12 months; 24-month share = min(due within 24 months / schedule, 1)",
      operands: {lines: String(input.lines.length), grossDebt: full(totalOnBalance), cash: full(cash), windows: String(input.maturityProfile.length)},
      result: `schedule=${full(totalSchedule)}; gap=${full(scheduleGap)}; weightedCost=${weightedCost ? full(weightedCost) : "none"}; due12=${full(maturing12)}; due24=${full(maturing24)}`,
    },
  };
}

// Leverage and covenants, before and after -----------------------------------------------------

export type DeskLeverage = {
  readonly netDebt: string;
  /** Net debt over EBITDA today; absent (null) over a zero EBITDA. */
  readonly preTurns: string | null;
  /** A company whose EBITDA is not positive has no turns to count: the desk reads its runway instead. */
  readonly profile: "cash_generative" | "cash_burning";
  /** Each amount the room states, at cents, with the leverage it would leave at four decimals (absent over a zero EBITDA), in the order stated. */
  readonly scenarios: ReadonlyArray<{readonly amount: string; readonly postTurns: string | null}>;
  /** The largest amount stated, at cents, never below zero. */
  readonly largestAmount: string;
  /**
   * The highest leverage the stated amounts leave (four decimals), never below zero, and whether it
   * exceeds leverage today; both absent over a zero EBITDA, where no leverage is compared.
   */
  readonly worstPostTurns: string | null;
  readonly worstPostAbovePre: boolean | null;
  /** The ratios a zero EBITDA left absent. */
  readonly absent: readonly AbsentRatio[];
  /** The tightest ceiling, the first listed among equals; null when no ceiling is stated. */
  readonly tightest: {readonly index: number} | null;
  /** The covenant arithmetic, when there is a ceiling and EBITDA is positive. */
  readonly covenant: {
    /** Ceiling x EBITDA - net debt: the new money the tightest covenant admits, negative when already above it. */
    readonly maxNewDebt: string;
    /** The same, never below zero, and its magnitude. */
    readonly roomForNewDebt: string;
    readonly excessNetDebt: string;
    readonly alreadyAbove: boolean;
    /** Whether an amount stated leaves leverage (at four decimals) above the ceiling. */
    readonly breached: boolean;
    /** The amount stated that leaves the highest leverage, the first among equals; null when none is stated. */
    readonly worstScenario: number | null;
  } | null;
  readonly trace: CalculationTrace;
};

/**
 * Net leverage before the ask and after each amount the room states, the tightest covenant ceiling
 * and the new money it admits: the number that changes the meeting.
 */
export function calculateDeskLeverage(input: {
  grossDebt: Decimal.Value;
  cash: Decimal.Value;
  ebitda: Decimal.Value;
  amounts: readonly Decimal.Value[];
  ceilings: readonly Decimal.Value[];
}): DeskLeverage {
  const grossDebt = finite("gross debt", input.grossDebt);
  const cash = finite("cash", input.cash);
  const ebitda = finite("EBITDA", input.ebitda);
  const netDebt = grossDebt.minus(cash);
  const preTurns = quotient(netDebt, ebitda);
  const amounts = input.amounts.map((amount, index) => finite(`amount ${index + 1}`, amount));
  const scenarios = amounts.map((amount) => {
    const post = quotient(netDebt.plus(amount), ebitda);
    return {amount: amount.toFixed(2), postTurns: post === null ? null : post.toFixed(4)};
  });
  const largestAmount = scenarios.reduce((max, scenario) => (new Decimal(scenario.amount).gt(max) ? new Decimal(scenario.amount) : max), ZERO);
  // Over a zero EBITDA every leverage is absent: none is ranked, none is compared with leverage today.
  const worstPost = preTurns === null ? null : scenarios.reduce((max, scenario) => Decimal.max(max, scenario.postTurns!), ZERO);
  const absent: AbsentRatio[] = preTurns === null
    ? [
        {ratio: "preTurns", denominator: "EBITDA"},
        ...scenarios.map((_, index) => ({ratio: `scenarios.${index}.postTurns`, denominator: "EBITDA"})),
        {ratio: "worstPostTurns", denominator: "EBITDA"},
      ]
    : [];

  const ceilings = input.ceilings.map((ceiling, index) => finite(`ceiling ${index + 1}`, ceiling));
  let tightest: {index: number; maximum: Decimal} | null = null;
  ceilings.forEach((maximum, index) => {
    if (!tightest || maximum.lt(tightest.maximum)) tightest = {index, maximum};
  });
  const bound = tightest as {index: number; maximum: Decimal} | null;
  const burning = ebitda.lte(0);

  let covenant: DeskLeverage["covenant"] = null;
  // The covenant arithmetic runs only over a positive EBITDA, where every leverage is a number.
  if (bound && !burning && preTurns !== null) {
    const maxNewDebt = bound.maximum.times(ebitda).minus(netDebt);
    const posts = scenarios.map((scenario) => new Decimal(scenario.postTurns!));
    covenant = {
      maxNewDebt: full(maxNewDebt),
      roomForNewDebt: full(Decimal.max(maxNewDebt, 0)),
      excessNetDebt: full(maxNewDebt.abs()),
      alreadyAbove: preTurns.gt(bound.maximum),
      breached: posts.some((post) => post.gt(bound.maximum)),
      worstScenario: posts.length === 0 ? null : posts.reduce((worst, post, index) => (post.gt(posts[worst]!) ? index : worst), 0),
    };
  }

  return {
    netDebt: full(netDebt),
    preTurns: preTurns === null ? null : full(preTurns),
    profile: burning ? "cash_burning" : "cash_generative",
    scenarios,
    largestAmount: full(largestAmount),
    worstPostTurns: worstPost === null ? null : full(worstPost),
    worstPostAbovePre: worstPost === null || preTurns === null ? null : worstPost.gt(preTurns),
    absent,
    tightest: bound ? {index: bound.index} : null,
    covenant,
    trace: {
      id: "desk.leverage",
      formula: "net debt = gross debt - cash; leverage = net debt / EBITDA, absent over a zero EBITDA; after an amount = (net debt + amount) / EBITDA at four decimals; "
        + "tightest = lowest ceiling, the first listed among equals; admitted new money = ceiling x EBITDA - net debt, only when EBITDA is positive",
      operands: {grossDebt: full(grossDebt), cash: full(cash), ebitda: full(ebitda), amounts: amounts.map(full).join(", "), ceilings: ceilings.map(full).join(", ")},
      result: `netDebt=${full(netDebt)}; pre=${traced(preTurns, "EBITDA")}; post=${scenarios.map((scenario) => traced(scenario.postTurns, "EBITDA")).join(", ")}${covenant ? `; admitted=${covenant.maxNewDebt}` : ""}`,
    },
  };
}

/**
 * Interest coverage today (EBITDA over the year's interest expense, as a magnitude) and with the
 * ask's interest added at its cost: the rate the company asks when it can be read, the stack's
 * weighted cost otherwise. Null when the expense or EBITDA is not positive, or no cost is known;
 * the coverage with the ask is absent, and listed in `absent`, when the interest it divides by
 * sums to zero.
 */
export function calculateInterestCoverage(input: {
  ebitda: Decimal.Value;
  financialExpenses: Decimal.Value | null;
  askAmount: Decimal.Value;
  askCost: Decimal.Value | null;
}): {readonly coverage: string | null; readonly coveragePost: string | null; readonly absent: readonly AbsentRatio[]; readonly trace: CalculationTrace} {
  const ebitda = finite("EBITDA", input.ebitda);
  const expenses = input.financialExpenses === null ? null : finite("financial expenses", input.financialExpenses).abs();
  const coverage = expenses && expenses.gt(0) && ebitda.gt(0) ? ebitda.div(expenses) : null;
  const askAmount = finite("amount asked", input.askAmount);
  const askCost = input.askCost === null ? null : finite("cost of the amount asked", input.askCost);
  const interestWithAsk = coverage && expenses && askCost ? expenses.plus(askAmount.times(askCost)) : null;
  const coveragePost = interestWithAsk ? quotient(ebitda, interestWithAsk) : null;
  const absent: AbsentRatio[] = interestWithAsk && interestWithAsk.isZero()
    ? [{ratio: "coveragePost", denominator: "interest expense plus the interest on the amount asked"}]
    : [];
  return {
    coverage: coverage ? full(coverage) : null,
    coveragePost: coveragePost ? full(coveragePost) : null,
    absent,
    trace: {
      id: "desk.interest_coverage",
      formula: "coverage = EBITDA / |interest expense|; with the ask = EBITDA / (|interest expense| + amount asked x its annual cost), absent when that interest is zero",
      operands: {ebitda: full(ebitda), financialExpenses: expenses ? full(expenses) : "none", askAmount: full(askAmount), askCost: askCost ? full(askCost) : "none"},
      result: `coverage=${coverage ? full(coverage) : "none"}; post=${coveragePost ? full(coveragePost) : absent.length > 0 ? "absent (zero interest with the ask)" : "none"}`,
    },
  };
}

/**
 * The runway a venture lender reads instead of turns: months of cash before the deal, months the
 * ticket buys, and months it buys once its own interest is paid monthly out of the same cash; debt
 * after the raise over ARR; and how far the runway the company states sits from the computed one.
 */
export function calculateVentureRunway(input: {
  cash: Decimal.Value;
  monthlyBurn: Decimal.Value;
  ask: Decimal.Value;
  assumedRate: Decimal.Value;
  grossDebt: Decimal.Value;
  arr: Decimal.Value | null;
  statedRunwayMonths: Decimal.Value | null;
}): {
  readonly monthsPre: string;
  readonly monthsPost: string;
  /** Absent (null) when the burn plus the ticket's monthly interest is zero. */
  readonly monthsPostAfterService: string | null;
  /** Months the deal buys after its own interest (absent with the runway after service), and before it. */
  readonly monthsBought: string | null;
  readonly monthsBoughtBeforeService: string;
  readonly debtAfterRaise: string;
  readonly debtToArr: string | null;
  /** |stated runway - computed runway|, when the company states one. */
  readonly statedGap: string | null;
  readonly absent: readonly AbsentRatio[];
  readonly trace: CalculationTrace;
} {
  const burn = finite("monthly burn", input.monthlyBurn);
  if (!burn.gt(0)) throw new RangeError("monthly burn must be positive");
  const cash = finite("cash", input.cash);
  const ask = finite("amount asked", input.ask);
  const rate = finite("assumed annual rate", input.assumedRate);
  const grossDebt = finite("gross debt", input.grossDebt);
  const monthsPre = cash.div(burn);
  const monthsPost = cash.plus(ask).div(burn);
  const monthlyInterest = ask.times(rate).div(12);
  const monthsPostAfterService = quotient(cash.plus(ask), burn.plus(monthlyInterest));
  const arr = input.arr === null ? null : finite("ARR", input.arr);
  const debtAfterRaise = grossDebt.plus(ask);
  const debtToArr = arr && arr.gt(0) ? debtAfterRaise.div(arr) : null;
  const statedGap = input.statedRunwayMonths === null ? null : finite("stated runway", input.statedRunwayMonths).minus(monthsPre).abs();
  const denominator = "monthly burn plus the ticket's monthly interest";
  const absent: AbsentRatio[] = monthsPostAfterService === null
    ? [{ratio: "monthsPostAfterService", denominator}, {ratio: "monthsBought", denominator}]
    : [];
  return {
    monthsPre: full(monthsPre),
    monthsPost: full(monthsPost),
    monthsPostAfterService: monthsPostAfterService === null ? null : full(monthsPostAfterService),
    monthsBought: monthsPostAfterService === null ? null : full(monthsPostAfterService.minus(monthsPre)),
    monthsBoughtBeforeService: full(monthsPost.minus(monthsPre)),
    debtAfterRaise: full(debtAfterRaise),
    debtToArr: debtToArr ? full(debtToArr) : null,
    statedGap: statedGap ? full(statedGap) : null,
    absent,
    trace: {
      id: "desk.runway",
      formula: "runway = cash / burn; with the ticket = (cash + ticket) / burn; after its interest = (cash + ticket) / (burn + ticket x rate / 12), absent when that denominator is zero; "
        + "debt to ARR = (gross debt + ticket) / ARR",
      operands: {cash: full(cash), monthlyBurn: full(burn), ask: full(ask), assumedRate: full(rate), grossDebt: full(grossDebt), arr: arr ? full(arr) : "none"},
      result: `pre=${full(monthsPre)}; post=${full(monthsPost)}; afterService=${traced(monthsPostAfterService, "burn plus interest")}; debtToArr=${debtToArr ? full(debtToArr) : "none"}`,
    },
  };
}

/**
 * The cash cycle and what growth absorbs: days of receivables over revenue, of inventory and of
 * suppliers over the cost of goods sold, the cycle they make, the working capital next year's
 * growth absorbs at that cycle, and whether the working-capital ask exceeds twice that need.
 */
export function calculateWorkingCapitalCycle(input: {
  revenue: Decimal.Value;
  receivables: Decimal.Value;
  cogs: Decimal.Value | null;
  inventory: Decimal.Value | null;
  suppliers: Decimal.Value | null;
  nextYearRevenue: Decimal.Value | null;
  workingCapitalAsk: Decimal.Value | null;
}): {
  readonly dso: string | null;
  readonly dio: string | null;
  readonly dpo: string | null;
  readonly cycleDays: string | null;
  readonly growth: string | null;
  readonly growthAbsorption: string | null;
  /**
   * Whether the working-capital ask exceeds twice what growth absorbs, and by how many times the need: absent when the
   * need is zero, and not a multiple (null) when the need is negative, because growth then releases working capital.
   */
  readonly askExceedsTwiceNeed: boolean;
  readonly askOverNeed: string | null;
  /** The working capital growth releases at a negative cycle (the magnitude of a negative need); null otherwise. */
  readonly growthRelease: string | null;
  /** The figures a zero cost of goods sold left absent (the days over it, the cycle, what growth absorbs), and the ask over a zero need. */
  readonly absent: readonly AbsentRatio[];
  readonly trace: CalculationTrace;
} {
  const revenue = finite("revenue", input.revenue);
  const cogs = input.cogs === null ? null : finite("cost of goods sold", input.cogs);
  const absent: AbsentRatio[] = [];
  const isAbsent = (ratio: string) => absent.some((entry) => entry.ratio === ratio);
  const COGS = "cost of goods sold";
  // Days over the cost of goods sold: not computed when the stock is not stated, absent over a zero cost.
  const daysOverCogs = (ratio: "dio" | "dpo", label: string, stock: Decimal.Value | null): Decimal | null => {
    if (!cogs || stock === null) return null;
    const share = quotient(finite(label, stock), cogs);
    if (share === null) absent.push({ratio, denominator: COGS});
    return share === null ? null : share.times(365);
  };
  const dso = revenue.gt(0) ? finite("receivables", input.receivables).div(revenue).times(365) : null;
  const dio = daysOverCogs("dio", "inventory", input.inventory);
  const dpo = daysOverCogs("dpo", "suppliers", input.suppliers);
  const cycle = dso && dio && dpo ? dso.plus(dio).minus(dpo) : null;
  // The cycle has all three legs or none: a leg absent over a zero cost leaves it absent, and what growth absorbs with it.
  const cycleAbsent = dso !== null && (dio !== null || isAbsent("dio")) && (dpo !== null || isAbsent("dpo")) && (isAbsent("dio") || isAbsent("dpo"));
  if (cycleAbsent) absent.push({ratio: "cycleDays", denominator: COGS});
  let growth: Decimal | null = null;
  let absorption: Decimal | null = null;
  let askOverNeed: Decimal | null = null;
  let askExceedsTwiceNeed = false;
  let release: Decimal | null = null;
  if ((cycle || cycleAbsent) && input.nextYearRevenue !== null) {
    growth = finite("next year's revenue", input.nextYearRevenue).minus(revenue);
    if (growth.gt(0)) {
      if (!cycle) absent.push({ratio: "growthAbsorption", denominator: COGS});
      else {
        absorption = growth.times(cycle).div(365);
        // A negative cycle releases working capital as revenue grows: the need is negative, and no ask is a multiple of it.
        if (absorption.lt(0)) release = absorption.neg();
        if (input.workingCapitalAsk !== null) {
          const ask = finite("working-capital ask", input.workingCapitalAsk);
          if (ask.gt(absorption.times(2))) {
            askExceedsTwiceNeed = true;
            if (!release) {
              askOverNeed = quotient(ask, absorption);
              if (askOverNeed === null) absent.push({ratio: "askOverNeed", denominator: "working capital that growth absorbs"});
            }
          }
        }
      }
    }
  }
  const text = (value: Decimal | null) => (value ? full(value) : null);
  const stated = (value: Decimal | null, ratio: string) => text(value) ?? (isAbsent(ratio) ? "absent" : "none");
  return {
    dso: text(dso),
    dio: text(dio),
    dpo: text(dpo),
    cycleDays: text(cycle),
    growth: text(growth),
    growthAbsorption: text(absorption),
    askExceedsTwiceNeed,
    askOverNeed: text(askOverNeed),
    growthRelease: text(release),
    absent,
    trace: {
      id: "desk.working_capital_cycle",
      formula: "DSO = receivables / revenue x 365; DIO = inventory / COGS x 365; DPO = suppliers / COGS x 365; cycle = DSO + DIO - DPO; "
        + "absorbed = growth of revenue x cycle / 365, when revenue grows; the ask is flagged above twice what is absorbed; "
        + "a figure over a zero COGS, and what depends on it, is absent; a negative need is working capital released, and the ask is no multiple of it",
      operands: {revenue: full(revenue), cogs: cogs ? full(cogs) : "none", nextYearRevenue: input.nextYearRevenue === null ? "none" : String(input.nextYearRevenue)},
      result: `cycle=${stated(cycle, "cycleDays")}; absorbed=${stated(absorption, "growthAbsorption")}; askOverNeed=${release ? `none (growth releases ${full(release)})` : stated(askOverNeed, "askOverNeed")}`,
    },
  };
}

/**
 * How free the receivables offered as security are: each line secured by receivables at a stated
 * coverage takes its balance times the coverage, a cession takes its balance, and what is left of
 * the base (never below zero) is free; the working-capital ask is read against it.
 */
export function calculateReceivablesEncumbrance(input: {
  base: Decimal.Value;
  lines: ReadonlyArray<{balance: Decimal.Value; coverage: Decimal.Value | null; cession: boolean}>;
  workingCapitalAsk: Decimal.Value | null;
}): {readonly encumbered: string; readonly free: string; readonly askAgainstFree: string | null; readonly trace: CalculationTrace} {
  const base = finite("receivables base", input.base);
  const encumbered = input.lines.reduce((sum, line, index) => {
    if (line.coverage !== null) return sum.plus(finite(`balance of line ${index + 1}`, line.balance).times(finite(`coverage of line ${index + 1}`, line.coverage)));
    return line.cession ? sum.plus(finite(`balance of line ${index + 1}`, line.balance)) : sum;
  }, ZERO);
  const free = Decimal.max(base.minus(encumbered), 0);
  const askAgainstFree = input.workingCapitalAsk !== null && free.gt(0) ? finite("working-capital ask", input.workingCapitalAsk).div(free) : null;
  return {
    encumbered: full(encumbered),
    free: full(free),
    askAgainstFree: askAgainstFree ? full(askAgainstFree) : null,
    trace: {
      id: "desk.receivables_encumbrance",
      formula: "encumbered = sum(balance x coverage) of lines secured by receivables + balance of lines with receivables ceded; free = max(base - encumbered, 0); ask against free = ask / free",
      operands: {base: full(base), lines: String(input.lines.length), workingCapitalAsk: input.workingCapitalAsk === null ? "none" : String(input.workingCapitalAsk)},
      result: `encumbered=${full(encumbered)}; free=${full(free)}; askAgainstFree=${askAgainstFree ? full(askAgainstFree) : "none"}`,
    },
  };
}

/** Whether the rate a company asks sits at or below the stack's weighted cost plus a tolerance: new money asking less than the stock costs. */
export function testRateAskAgainstStack(input: {askRate: Decimal.Value; stackCost: Decimal.Value; tolerance: Decimal.Value}): {
  readonly atOrBelowStack: boolean;
  readonly limit: string;
  readonly trace: CalculationTrace;
} {
  const ask = finite("rate asked", input.askRate);
  const stack = finite("stack's weighted cost", input.stackCost);
  const tolerance = finite("tolerance", input.tolerance);
  const limit = stack.plus(tolerance);
  const atOrBelowStack = ask.lte(limit);
  return {
    atOrBelowStack,
    limit: full(limit),
    trace: {id: "desk.rate_ask_vs_stack", formula: "flagged when the rate asked <= the stack's weighted cost + tolerance", operands: {askRate: full(ask), stackCost: full(stack), tolerance: full(tolerance)}, result: atOrBelowStack ? "at_or_below_stack" : "above_stack"},
  };
}

// The trajectory ---------------------------------------------------------------------------------

/**
 * Proceeds that repay existing debt leave the stack on day one, nearest maturity first: a company
 * pays down what is about to fall due, which is why it raises. The refinancing is capped at the
 * stack; each line keeps what is left of it, at cents, in the order given.
 */
export function allocateRefinancingNearestFirst(input: {lines: ReadonlyArray<{balance: Decimal.Value; maturity: string | null}>; refinancing: Decimal.Value}): {
  readonly existingTotal: string;
  readonly refinancing: string;
  readonly remaining: readonly string[];
  readonly trace: CalculationTrace;
} {
  const balances = input.lines.map((line, index) => finite(`balance of line ${index + 1}`, line.balance));
  const existingTotal = balances.reduce((sum, balance) => sum.plus(balance), ZERO);
  const refinancing = Decimal.min(finite("refinancing", input.refinancing), existingTotal);
  const order = input.lines.map((_, index) => index)
    .sort((a, b) => (input.lines[a]!.maturity ?? "9999-12-31").localeCompare(input.lines[b]!.maturity ?? "9999-12-31"));
  const redeemed: Array<Decimal | null> = balances.map(() => null);
  let toRedeem = refinancing;
  for (const index of order) {
    if (toRedeem.lte(0)) break;
    const take = Decimal.min(toRedeem, balances[index]!);
    redeemed[index] = take;
    toRedeem = toRedeem.minus(take);
  }
  const remaining = balances.map((balance, index) => balance.minus(redeemed[index] ?? 0).toFixed(2));
  return {
    existingTotal: full(existingTotal),
    refinancing: full(refinancing),
    remaining,
    trace: {
      id: "desk.refinancing_redemption",
      formula: "refinancing = min(refinancing, stack); redeemed nearest maturity first, a line without maturity last; each line keeps its balance less what it redeems, at cents",
      operands: {refinancing: String(input.refinancing), stack: full(existingTotal)},
      result: `redeemed=${redeemed.map((value) => (value ? full(value) : "0")).join(", ")}`,
    },
  };
}

export type LeveragePathYear = {
  year: number;
  existingDebt: string;
  newDebt: string;
  netDebt: string;
  ebitdaBase: string;
  ebitdaStressed: string;
  /** Absent (null) when the year's projected EBITDA is zero. */
  leverageBase: string | null;
  /** Absent (null) when the year's EBITDA in the stressed case is zero. */
  leverageStressed: string | null;
  principalDue: string;
  /** Absent (null) when the year's projected EBITDA is zero. */
  scheduleStrain: string | null;
};

/**
 * Leverage year by year once a new loan lands: existing lines run to their own schedules (linear to
 * maturity when they amortise, bullets otherwise, flat when they state no maturity), the new loan is
 * flat through grace and SAC afterwards, cash is held flat, and EBITDA is the company's projection
 * and a stressed one that believes only part of the growth over the audited base. Amounts at cents
 * and ratios at four decimals, as the trajectory publishes them. Then the peak (the highest stressed
 * leverage, the first year among equals), the first year under each existing ceiling, and the
 * covenant step-down: the stressed leverage plus a cushion, up to the next quarter turn, never below
 * a floor.
 *
 * A year whose EBITDA is zero has no leverage and no strain in that case: they are absent, and an
 * absent leverage is never compared. The peak is the highest of all the years, so one absent
 * stressed leverage leaves the peak absent (null); a crossing is the first year whose leverage is a
 * number at or under the ceiling; the covenant step of a year without a stressed leverage is absent.
 */
export function projectLeveragePath(input: {
  /** year x 12 + month - 1 of the reference date, which is also the disbursement. */
  referenceMonth: number;
  cash: Decimal.Value;
  newDebt: {amount: Decimal.Value; termMonths: number; graceMonths: number};
  lines: ReadonlyArray<{balance: Decimal.Value; maturityMonth: number | null; amortizes: boolean}>;
  auditedEbitda: Decimal.Value;
  growthHaircut: Decimal.Value;
  covenantCushion: Decimal.Value;
  covenantFloor: Decimal.Value;
  years: ReadonlyArray<{year: number; ebitda: Decimal.Value}>;
  ceilings: readonly Decimal.Value[];
}): {
  readonly years: readonly LeveragePathYear[];
  /** The year of the highest stressed leverage; null when a year's stressed leverage is absent. */
  readonly peakIndex: number | null;
  readonly ceilings: readonly string[];
  readonly crossings: ReadonlyArray<{maximum: string; yearBase: number | null; yearStressed: number | null}>;
  /** The step of each year; absent (null) when the year's stressed leverage is. */
  readonly covenantProposal: ReadonlyArray<{year: number; maximum: string | null}>;
  /** The ratios a zero EBITDA left absent, by year (`2027.leverageBase`), and the covenant steps and the peak with them. */
  readonly absent: readonly AbsentRatio[];
  readonly trace: CalculationTrace;
} {
  if (input.years.length === 0) throw new RangeError("the trajectory needs at least one projected year");
  const reference = input.referenceMonth;
  const cash = finite("cash", input.cash);
  const amount = finite("new debt", input.newDebt.amount);
  const audited = finite("audited EBITDA", input.auditedEbitda);
  const haircut = finite("growth haircut", input.growthHaircut);
  const cushion = finite("covenant cushion", input.covenantCushion);
  const floor = finite("covenant floor", input.covenantFloor);
  const lines = input.lines.map((line, index) => ({...line, balance: finite(`balance of line ${index + 1}`, line.balance)}));

  const existingAt = (line: (typeof lines)[number], at: number): Decimal => {
    if (at <= reference) return line.balance;
    if (line.maturityMonth === null) return line.balance;
    if (at >= line.maturityMonth) return new Decimal(0);
    if (!line.amortizes) return line.balance;
    const total = line.maturityMonth - reference;
    const elapsed = at - reference;
    return line.balance.times(total - elapsed).div(total);
  };
  const newDebtAt = (at: number): Decimal => {
    if (at <= reference) return amount;
    const amortMonths = input.newDebt.termMonths - input.newDebt.graceMonths;
    const amortised = Math.min(Math.max(at - reference - input.newDebt.graceMonths, 0), amortMonths);
    return amount.times(amortMonths - amortised).div(amortMonths);
  };

  const fourDecimals = (value: Decimal | null) => (value === null ? null : value.toFixed(4));
  const years: LeveragePathYear[] = input.years.map(({year, ebitda}) => {
    const at = year * 12 + 11; // December of the year.
    const previous = Math.max((year - 1) * 12 + 11, reference);
    const existingNow = lines.reduce((sum, line) => sum.plus(existingAt(line, at)), new Decimal(0));
    const existingPrevious = lines.reduce((sum, line) => sum.plus(existingAt(line, previous)), new Decimal(0));
    const newNow = newDebtAt(at);
    const newPrevious = newDebtAt(previous);
    const netDebt = existingNow.plus(newNow).minus(cash);
    const base = finite(`EBITDA of ${year}`, ebitda);
    const stressed = audited.plus(Decimal.max(base.minus(audited), 0).times(new Decimal(1).minus(haircut)));
    const principalDue = existingPrevious.minus(existingNow).plus(newPrevious.minus(newNow));
    return {
      year,
      existingDebt: existingNow.toFixed(2),
      newDebt: newNow.toFixed(2),
      netDebt: netDebt.toFixed(2),
      ebitdaBase: base.toFixed(2),
      ebitdaStressed: stressed.toFixed(2),
      leverageBase: fourDecimals(quotient(netDebt, base)),
      leverageStressed: fourDecimals(quotient(netDebt, stressed)),
      principalDue: principalDue.toFixed(2),
      scheduleStrain: fourDecimals(quotient(principalDue, base)),
    };
  });

  const absent: AbsentRatio[] = years.flatMap((row) => [
    ...(row.leverageBase === null ? [{ratio: `${row.year}.leverageBase`, denominator: `projected EBITDA of ${row.year}`}] : []),
    ...(row.leverageStressed === null ? [{ratio: `${row.year}.leverageStressed`, denominator: `stressed EBITDA of ${row.year}`}] : []),
    ...(row.scheduleStrain === null ? [{ratio: `${row.year}.scheduleStrain`, denominator: `projected EBITDA of ${row.year}`}] : []),
  ]);
  // The highest of all the years: one absent stressed leverage leaves the peak absent, never ranked around it.
  const peakIndex = years.some((row) => row.leverageStressed === null)
    ? null
    : years.reduce((peak, row, index) => (new Decimal(row.leverageStressed!).gt(years[peak]!.leverageStressed!) ? index : peak), 0);
  const ceilings = [...new Set(input.ceilings.map((ceiling, index) => finite(`ceiling ${index + 1}`, ceiling).toFixed(4)))]
    .sort((a, b) => new Decimal(a).comparedTo(b));
  // The first year whose leverage is a number at or under the ceiling; an absent leverage is not compared.
  const atOrUnder = (value: string | null, maximum: string) => value !== null && new Decimal(value).lte(maximum);
  const crossings = ceilings.map((maximum) => ({
    maximum,
    yearBase: years.find((row) => atOrUnder(row.leverageBase, maximum))?.year ?? null,
    yearStressed: years.find((row) => atOrUnder(row.leverageStressed, maximum))?.year ?? null,
  }));
  const covenantProposal = years.map((row) => {
    if (row.leverageStressed === null) return {year: row.year, maximum: null};
    const stepped = new Decimal(row.leverageStressed).plus(cushion);
    const rounded = stepped.times(4).ceil().div(4); // to the nearest upper quarter turn
    return {year: row.year, maximum: Decimal.max(rounded, floor).toFixed(2)};
  });
  for (const step of covenantProposal) {
    if (step.maximum === null) absent.push({ratio: `${step.year}.covenantStep`, denominator: `stressed EBITDA of ${step.year}`});
  }
  if (peakIndex === null) absent.push({ratio: "peak", denominator: "stressed EBITDA of a year"});

  return {
    years,
    peakIndex,
    ceilings,
    crossings,
    covenantProposal,
    absent,
    trace: {
      id: "desk.leverage_path",
      formula: "per year-end: existing = own schedule (linear to maturity when amortising); new = flat through grace, SAC after; net debt = existing + new - cash; "
        + "stressed EBITDA = audited + max(projected - audited, 0) x (1 - haircut); leverage = net debt / EBITDA; principal due = fall of the balances in the year; strain = principal due / EBITDA; "
        + "peak = highest stressed leverage, the first year among equals; crossing = first year at or under each ceiling; covenant = max(ceil((stressed + cushion) x 4) / 4, floor); "
        + "over a zero EBITDA the leverage, the strain and the covenant step are absent, and an absent stressed leverage leaves the peak absent",
      operands: {cash: full(cash), newDebt: full(amount), termMonths: String(input.newDebt.termMonths), graceMonths: String(input.newDebt.graceMonths), auditedEbitda: full(audited), growthHaircut: full(haircut), covenantCushion: full(cushion), covenantFloor: full(floor)},
      result: `peak=${peakIndex === null ? "absent" : `${years[peakIndex]!.year}:${years[peakIndex]!.leverageStressed}`}; covenant=${covenantProposal.map((step) => `${step.year}:${step.maximum ?? "absent"}`).join(", ")}`,
    },
  };
}

/**
 * Liability management: the part of a ticket that redeems existing debt at disbursement (the
 * covenanted lines taken out, or the refinancing the room states) and the new money left, and net
 * leverage once the structure lands on the audited EBITDA, on the same base as leverage today: the
 * debt before, less what is redeemed, plus the ticket. Every term is an amount in cents, so the sum
 * is exact at 40 significant digits in any order. Over a zero EBITDA the leverage after is absent.
 */
export function calculateLiabilityManagement(input: {
  ticket: Decimal.Value;
  redeemed: readonly Decimal.Value[];
  grossDebtBefore: Decimal.Value;
  cash: Decimal.Value;
  ebitda: Decimal.Value;
}): {readonly redeemed: string; readonly netNewMoney: string; readonly leverageAfter: string | null; readonly absent: readonly AbsentRatio[]; readonly trace: CalculationTrace} {
  const ticket = finite("ticket", input.ticket);
  const redeemed = input.redeemed.reduce<Decimal>((sum, value, index) => sum.plus(finite(`redeemed ${index + 1}`, value)), new Decimal(0));
  const before = finite("gross debt before", input.grossDebtBefore);
  const cash = finite("cash", input.cash);
  const ebitda = finite("EBITDA", input.ebitda);
  const netNewMoney = ticket.minus(redeemed);
  const after = before.minus(redeemed).plus(ticket);
  const leverageAfter = quotient(after.minus(cash), ebitda);
  return {
    redeemed: full(redeemed),
    netNewMoney: full(netNewMoney),
    leverageAfter: leverageAfter === null ? null : full(leverageAfter),
    absent: leverageAfter === null ? [{ratio: "leverageAfter", denominator: "EBITDA"}] : [],
    trace: {
      id: "desk.liability_management",
      formula: "new money = ticket - redeemed; leverage after = (gross debt before - redeemed + ticket - cash) / EBITDA, absent over a zero EBITDA",
      operands: {ticket: full(ticket), redeemed: full(redeemed), grossDebtBefore: full(before), cash: full(cash), ebitda: full(ebitda)},
      result: `newMoney=${full(netNewMoney)}; leverageAfter=${traced(leverageAfter, "EBITDA")}`,
    },
  };
}

