import {methodDataContractSchema, type MethodValueType} from "./method-component";

type Schema = Record<string, unknown>;
const object = (raw: unknown): Schema => {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) throw new Error("method_json_schema_object_required");
  return raw as Schema;
};
/** Structural projection for build-owned executor registration. Runtime schemas retain
 * refinements, bounds, literals and formats; pin their source bytes and the full JSON schema.
 * This projection never substitutes for the executor's semantic input/output validation. */
export function methodDataContractFromJsonSchema(id: string, version: string, raw: unknown) {
  function project(raw: unknown): MethodValueType {
    const s = object(raw);
    if (s.$ref || s.allOf || s.not || s.if || s.patternProperties) throw new Error("method_json_schema_unsupported_composition");
    const variants = s.anyOf ?? s.oneOf;
    if (variants !== undefined) {
      if (!Array.isArray(variants) || variants.length < 2) throw new Error("method_json_schema_variants_required");
      return {type: "union", variants: variants.map(project)};
    }
    if (Array.isArray(s.type)) return {type: "union", variants: s.type.map(type => project({...s, type}))};
    const type = s.type;
    // JSON Schema represents a numeric literal as number even when it is an integer.
    if (type === "number" && Number.isSafeInteger(s.const)) return {type: "integer"};
    if (type === "null" || type === "boolean" || type === "integer") return {type};
    if (type === "string") {
      const values = s.enum ?? (typeof s.const === "string" ? [s.const] : undefined);
      if (values !== undefined) {
        if (!Array.isArray(values) || !values.length || values.some(v => typeof v !== "string" || !v.length)) throw new Error("method_json_schema_string_enum_required");
        return {type: "enum", values: values as string[]};
      }
      if (s.format === "date") return {type: "date"};
      if (s.pattern === "^-?\\d+(?:\\.\\d+)?$") return {type: "decimal_string"};
      return {type: "string"};
    }
    if (type === "array") {
      if (!s.items || s.prefixItems) throw new Error("method_json_schema_typed_array_required");
      return {type: "array", items: project(s.items)};
    }
    if (type === "object") {
      if (s.additionalProperties && typeof s.additionalProperties === "object" && !Array.isArray(s.additionalProperties)) {
        if (s.required !== undefined && !Array.isArray(s.required)) throw new Error("method_json_schema_required_field_missing");
        if ((s.properties && Object.keys(object(s.properties)).length) || (Array.isArray(s.required) && s.required.length)) throw new Error("method_json_schema_mixed_record_unsupported");
        return {type: "map", values: project(s.additionalProperties)};
      }
      if (s.additionalProperties !== false) throw new Error("method_json_schema_closed_object_required");
      const properties = object(s.properties); const required = s.required ?? [];
      if (!Array.isArray(required) || required.some(k => typeof k !== "string" || !Object.hasOwn(properties, k))) throw new Error("method_json_schema_required_field_missing");
      return {type: "object", fields: Object.fromEntries(Object.entries(properties).map(([key, value]) => [key, {required: required.includes(key), value: project(value)}]))};
    }
    throw new Error("method_json_schema_unsupported_or_opaque_type");
  }
  return methodDataContractSchema.parse({id, version, value: project(raw)});
}

packages/credit-playbook/src/conventions.content:
import {z} from "zod";
import {referenceDataEntrySchema, referenceDataRegistry, referenceDataStatusSchema, type ReferenceDataStatus} from "./reference-data";

/**
 * Date-aware reading of the versioned reference data behind a calculation (IOF, ANBIMA/B3
 * conventions, tax regime). A key is effective only when its entry is approved and the reference
 * date falls inside the closed window [asOf, validUntil]. Every other case is a gap with a reason:
 * unknown key, malformed entry, invalid reference date, a status other than approved, a window
 * that has not opened yet or one that has closed. The gate reads what the registry holds; it never
 * supplies a value, a default or an estimate in place of a missing one.
 */
export const conventionsGateVersion = "2026.09.24-v1";

export const conventionsGapReasonSchema = z.enum([
  "unknown_key",
  "malformed_entry",
  "invalid_reference_date",
  "status_required_missing",
  "status_draft",
  "status_expired",
  "not_yet_effective",
  "expired",
]);
export type ConventionsGapReason = z.infer<typeof conventionsGapReasonSchema>;

export type ConventionsGateEntry = {
  key: string;
  /** Registry metadata as found; null when the key is unknown or the field is unreadable. */
  version: string | null;
  status: ReferenceDataStatus | null;
  owner: string | null;
  effective: "approved" | "gap";
  /** Present exactly when `effective` is `gap`. */
  reason?: ConventionsGapReason;
};

export type ConventionsGateResult = {
  version: typeof conventionsGateVersion;
  referenceDate: string;
  /** One entry per distinct key, in first-seen order. */
  entries: ConventionsGateEntry[];
  /** Keys whose entry is a gap, in the same order. */
  gaps: string[];
};

export type ConventionsGateOptions = {
  /** The registry to read. Defaults to the house registry; tests inject synthetic entries here. */
  registry?: readonly unknown[];
};

type EntryMetadata = Pick<ConventionsGateEntry, "version" | "status" | "owner">;

const isoDateSchema = z.iso.date();
const unknownMetadata: EntryMetadata = {version: null, status: null, owner: null};

export function evaluateConventionsGate(
  keys: readonly string[],
  referenceDate: string,
  options: ConventionsGateOptions = {},
): ConventionsGateResult {
  const registry = options.registry ?? referenceDataRegistry;
  const referenceDateIsValid = isoDateSchema.safeParse(referenceDate).success;
  const entries: ConventionsGateEntry[] = [];
  const seen = new Set<string>();
  for (const key of keys) {
    if (seen.has(key)) continue;
    seen.add(key);
    entries.push(evaluateKey(key, referenceDate, referenceDateIsValid, registry));
  }
  return {
    version: conventionsGateVersion,
    referenceDate,
    entries,
    gaps: entries.filter((entry) => entry.effective === "gap").map((entry) => entry.key),
  };
}

function evaluateKey(key: string, referenceDate: string, referenceDateIsValid: boolean, registry: readonly unknown[]): ConventionsGateEntry {
  const raw = registry.find((candidate) => isRecord(candidate) && candidate.key === key);
  if (raw === undefined) return gap(key, unknownMetadata, "unknown_key");
  const parsed = referenceDataEntrySchema.safeParse(raw);
  if (!parsed.success) return gap(key, metadataOf(raw), "malformed_entry");
  const entry = parsed.data;
  const metadata: EntryMetadata = {version: entry.version, status: entry.status, owner: entry.owner};
  if (!referenceDateIsValid) return gap(key, metadata, "invalid_reference_date");
  if (entry.status !== "approved") return gap(key, metadata, `status_${entry.status}`);
  // The schema already refuses an approved entry without both dates; this keeps the narrowing honest.
  if (entry.asOf === null || entry.validUntil === null) return gap(key, metadata, "malformed_entry");
  // ISO calendar dates compare correctly as strings.
  if (referenceDate < entry.asOf) return gap(key, metadata, "not_yet_effective");
  if (referenceDate > entry.validUntil) return gap(key, metadata, "expired");
  return {key, ...metadata, effective: "approved"};
}

function gap(key: string, metadata: EntryMetadata, reason: ConventionsGapReason): ConventionsGateEntry {
  return {key, ...metadata, effective: "gap", reason};
}

function metadataOf(raw: unknown): EntryMetadata {
  if (!isRecord(raw)) return unknownMetadata;
  const status = referenceDataStatusSchema.safeParse(raw.status);
  return {
    version: typeof raw.version === "string" ? raw.version : null,
    status: status.success ? status.data : null,
    owner: typeof raw.owner === "string" ? raw.owner : null,
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

packages/financial-core/src/figure-input.content:
import Decimal from "decimal.js";

/**
 * How every kernel of the materials, the desk and the price reference reads a figure it receives
 * (internal to the package). Decimal notation only: text in another notation (hexadecimal, binary,
 * `Infinity`, `NaN`) and a number that is not finite are not figures, and a kernel refuses them
 * instead of reading them as zero.
 */
const decimalText = /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/;

/** The figure as a decimal, or null when the value is not a finite decimal number. */
export function parseFigure(value: Decimal.Value): Decimal | null {
  if (typeof value === "string" && !decimalText.test(value)) return null;
  if (typeof value === "number" && !Number.isFinite(value)) return null;
  const parsed = new Decimal(value);
  return parsed.isFinite() ? parsed : null;
}

/** The figure as a decimal; refuses a value that is not a finite decimal number, naming it. */
export function finiteFigure(label: string, value: Decimal.Value): Decimal {
  const parsed = parseFigure(value);
  if (!parsed) throw new RangeError(`${label} must be a finite decimal number`);
  return parsed;
}

/** A decimal at full precision, without rounding: the figure a kernel hands on. */
export const fullFigure = (value: Decimal): string => value.toFixed();

packages/credit-playbook/src/method-sele.content:
import {z} from "zod";

/**
 * Section R3 ("Seleção de métodos") of the capital procedure as data: the situations a decision
 * can sit in, the methods that must structure the analysis for each one and the method that alone
 * misleads. The three texts are literal copies of the table cells; the engineering association
 * (`servedBy`) says which house method serves the situation today. Selecting a method for a
 * situation the method does not serve is refused, never silently accepted.
 */
export const methodSelectionVersion = "2026.09.24-v1";

export const methodSelectionSource = {
  procedureId: "prepare-capital-structure-decision",
  procedurePath: "capital/prepare-capital-structure-decision.md",
  section: "R3. Seleção de métodos",
} as const;

/** The integrated capital procedure. */
export const capitalStructureMethodId = "prepare-capital-structure-decision";
/** The receivables method behind task R01 (`underwrite-receivables-pool`, bound to `taskIds: ["R01"]` in the runtime manifest). */
export const receivablesPoolMethodId = "underwrite-receivables-pool";

export type StructuringSituation = {
  /** Stable engineering id, kebab-case. */
  situationId: string;
  /** The "Situação" cell, verbatim. */
  label: string;
  /** The "Métodos que devem estruturar a análise" cell, verbatim. */
  structuringMethods: string;
  /** The "Método que isoladamente engana" cell, verbatim. */
  misleadingAlone: string;
  /** House methods (procedure ids) that serve the situation today. */
  servedBy: readonly string[];
};

export const structuringSituations = [
  {situationId: "seasonal-working-capital", label: "Giro sazonal", structuringMethods: "Fluxo direto de 13 semanas, extensão mensal, ciclo financeiro, NCG/Fleuriet e cobertura no pior período.", misleadingAlone: "EBITDA ou DSCR anual que esconde o mês de falta de caixa.", servedBy: [capitalStructureMethodId]},
  {situationId: "structural-working-capital", label: "Giro estrutural", structuringMethods: "Fleuriet em série, NCG/receita, ciclo de conversão e fluxo indireto; carteira quando relevante.", misleadingAlone: "Fluxo curto sem explicar a necessidade permanente.", servedBy: [capitalStructureMethodId]},
  {situationId: "capex-infrastructure", label: "Capex/infraestrutura", structuringMethods: "Manutenção separada de expansão, construção e maturação; DSCR por período e, em projeto, LLCR/PLCR.", misleadingAlone: "EBITDA corrente durante construção.", servedBy: [capitalStructureMethodId]},
  {situationId: "stable-business-high-conversion", label: "Negócio estável com alta conversão", structuringMethods: "Cadeia EBITDA a caixa, FCF/dívida, cobertura e alavancagem nas definições pertinentes.", misleadingAlone: "Métrica de projeto aplicada sem finalidade.", servedBy: [capitalStructureMethodId]},
  {situationId: "near-covenant", label: "Próxima de covenant", structuringMethods: "Curva por contrato/data/caso, teste reverso, liquidez 12/24 meses e refinanciamento.", misleadingAlone: "Preço como critério principal.", servedBy: [capitalStructureMethodId]},
  {situationId: "growth-without-ebitda", label: "Crescimento sem EBITDA", structuringMethods: "Queima, pista de caixa, unit economics, compromissos e próxima rodada sob atraso.", misleadingAlone: "Múltiplo de EBITDA, DSCR ou régua de agência sem aplicabilidade.", servedBy: [capitalStructureMethodId]},
  {situationId: "holding-group", label: "Holding/grupo", structuringMethods: "Caixa que pode subir, dívida individual, subordinação, dupla alavancagem e garantias cruzadas.", misleadingAlone: "Consolidado sozinho.", servedBy: [capitalStructureMethodId]},
  {situationId: "receivables", label: "Recebíveis", structuringMethods: "Aging, concentração, diluição, roll-rate, elegibilidade, avanço, subordinação e custo do veículo.", misleadingAlone: "Tratar carteira como companhia ou garantia nominal como caixa.", servedBy: [receivablesPoolMethodId]},
  {situationId: "restructuring", label: "Reestruturação", structuringMethods: "Fluxo direto, prioridades de credores, garantias, liquidez e alongamentos suportáveis.", misleadingAlone: "Referência normal de mercado como condição disponível.", servedBy: [capitalStructureMethodId]},
  {situationId: "acquisition-bridge", label: "Aquisição/ponte", structuringMethods: "Fontes e usos, combinado, cláusulas, capacidade e certeza do take-out, inclusive atraso.", misleadingAlone: "Sinergias integrais sem evidência ou balanço isolado da adquirente.", servedBy: [capitalStructureMethodId]},
  {situationId: "refinancing", label: "Refinanciamento", structuringMethods: "Torre, caixa, custo e prazo da substituição, liberação de garantias e condições.", misleadingAlone: "Comparar apenas spread.", servedBy: [capitalStructureMethodId]},
  {situationId: "unaudited-divergent-numbers", label: "Números não auditados/divergentes", structuringMethods: "Conciliação gerencial-contábil, conversão em caixa, sanidade do giro e histórico bancário disponível.", misleadingAlone: "EBITDA gerencial sem reconciliação.", servedBy: [capitalStructureMethodId]},
] as const satisfies readonly StructuringSituation[];

export type StructuringSituationId = (typeof structuringSituations)[number]["situationId"];

export type MethodSelectionInput = {
  situationIds: readonly string[];
  methodId: string;
  methodVersion: string;
};

export type MethodSelectionReasonCode =
  /** Every selected situation lists the method. */
  | "all_situations_served"
  /** At least one selected situation lists the method and at least one does not. */
  | "partial_coverage"
  /** More than one situation was selected; the decision crosses situations. */
  | "decision_crosses_situations";

export type SelectedSituation = {
  situationId: string;
  label: string;
  servedByMethod: boolean;
  misleadingAlone: string;
};

export type MethodSelectionRecord = {
  selectionVersion: typeof methodSelectionVersion;
  /** Distinct selected situations, in selection order. */
  situations: SelectedSituation[];
  methodId: string;
  methodVersion: string;
  /** The method that alone misleads, one literal text per selected situation, in the same order. */
  misleadingAlone: string[];
  reasonCodes: MethodSelectionReasonCode[];
};

export type MethodSelectionRefusalCode =
  | "input_invalid"
  | "situation_required"
  | "situation_unknown"
  | "method_not_applicable_for_situation";

/** A typed refusal: the selection is not recorded and the caller gets the code and the ids involved. */
export class MethodSelectionRefusal extends Error {
  constructor(readonly code: MethodSelectionRefusalCode, readonly situationIds: readonly string[], detail: string) {
    super(`${code}: ${detail}`);
    this.name = "MethodSelectionRefusal";
  }
}

const inputSchema = z.object({
  situationIds: z.array(z.string()),
  methodId: z.string().regex(/^[a-z][a-z0-9-]{2,79}$/),
  methodVersion: z.string().regex(/^\d{4}\.\d{2}\.\d{2}-v\d+$/),
}).strict();

const byId = new Map<string, StructuringSituation>(structuringSituations.map((situation) => [situation.situationId, situation]));

export function selectMethod(input: MethodSelectionInput): MethodSelectionRecord {
  const parsed = inputSchema.safeParse(input);
  if (!parsed.success) throw new MethodSelectionRefusal("input_invalid", [], parsed.error.issues.map((issue) => `${issue.path.join(".")}: ${issue.message}`).join("; "));
  const {situationIds, methodId, methodVersion} = parsed.data;
  if (situationIds.length === 0) throw new MethodSelectionRefusal("situation_required", [], "no situation was selected");
  const unknown = situationIds.filter((id) => !byId.has(id));
  if (unknown.length > 0) throw new MethodSelectionRefusal("situation_unknown", unknown, `unknown situation ${unknown.join(", ")}`);
  const selected = [...new Set(situationIds)].map((id) => byId.get(id)!);
  const served = selected.filter((situation) => situation.servedBy.includes(methodId));
  if (served.length === 0) {
    throw new MethodSelectionRefusal("method_not_applicable_for_situation", selected.map((situation) => situation.situationId), `${methodId} serves none of the selected situations`);
  }
  const reasonCodes: MethodSelectionReasonCode[] = [served.length === selected.length ? "all_situations_served" : "partial_coverage"];
  if (selected.length > 1) reasonCodes.push("decision_crosses_situations");
  return {
    selectionVersion: methodSelectionVersion,
    situations: selected.map((situation) => ({
      situationId: situation.situationId,
      label: situation.label,
      servedByMethod: situation.servedBy.includes(methodId),
      misleadingAlone: situation.misleadingAlone,
    })),
    methodId,
    methodVersion,
    misleadingAlone: selected.map((situation) => situation.misleadingAlone),
    reasonCodes,
  };
}

