/**
 * Financial definitions (Blueprint §15.2). Definitions are parameters of a
 * transaction, never hidden constants: the financial-core receives them
 * explicitly and records the definition id + version in every calculation trace.
 * The platform never suggests a single universal EBITDA/CFADS/DSCR exists.
 */
export type FinancialDefinition = {
  id: string;
  version: string;
  labels: {pt: string; en: string};
  /** Human-readable formula using account codes / metric ids. */
  formula: string;
  inputs: string[];
  notes: {pt: string; en: string};
};

export const financialDefinitions: readonly FinancialDefinition[] = [
  {
    id: "adjusted_ebitda",
    version: "v1",
    labels: {pt: "EBITDA ajustado", en: "Adjusted EBITDA"},
    formula: "is_ebitda + approved_nonrecurring_expenses - nonrecurring_income - unsupported_or_low_confidence_addbacks",
    inputs: ["is_ebitda", "approved_nonrecurring_expenses", "nonrecurring_income", "unsupported_or_low_confidence_addbacks"],
    notes: {
      pt: "Cada ajuste é aprovado individualmente com fonte; add-backs sem suporte não entram.",
      en: "Each adjustment is approved individually with a source; unsupported add-backs are excluded.",
    },
  },
  {
    id: "cfads",
    version: "v1",
    labels: {pt: "CFADS", en: "CFADS"},
    formula: "adjusted_ebitda - taxes_paid - maintenance_capex - normalized_working_capital_investment - fixed_charges_not_yet_reflected +/- approved_cash_adjustments",
    inputs: ["adjusted_ebitda", "taxes_paid", "maintenance_capex", "normalized_working_capital_investment", "fixed_charges_not_yet_reflected", "approved_cash_adjustments"],
    notes: {
      pt: "Capex de manutenção e capital de giro normalizado são premissas explícitas por transação.",
      en: "Maintenance capex and normalized working capital are explicit per-transaction assumptions.",
    },
  },
  {
    id: "dscr",
    version: "v1",
    labels: {pt: "DSCR", en: "DSCR"},
    formula: "cfads / scheduled_cash_debt_service",
    inputs: ["cfads", "scheduled_cash_debt_service"],
    notes: {pt: "Serviço da dívida em caixa programado (principal + juros) do período.", en: "Scheduled cash debt service (principal + interest) for the period."},
  },
  {
    id: "interest_coverage",
    version: "v1",
    labels: {pt: "Cobertura de juros", en: "Interest coverage"},
    formula: "selected_earnings_measure / cash_interest_paid",
    inputs: ["selected_earnings_measure", "cash_interest_paid"],
    notes: {pt: "A medida de resultado (EBITDA, EBITDA ajustado, EBIT) é escolhida por transação.", en: "The earnings measure (EBITDA, adjusted EBITDA, EBIT) is chosen per transaction."},
  },
  {
    id: "collateral_coverage",
    version: "v1",
    labels: {pt: "Cobertura de garantias", en: "Collateral coverage"},
    formula: "eligible_value_after_haircut / secured_exposure",
    inputs: ["eligible_value_after_haircut", "secured_exposure"],
    notes: {pt: "Haircuts vêm da política vigente e ficam registrados por ativo.", en: "Haircuts come from the current policy and are recorded per asset."},
  },
  {
    id: "net_debt",
    version: "v1",
    labels: {pt: "Dívida líquida", en: "Net debt"},
    formula: "gross_debt - cash - short_term_investments",
    inputs: ["gross_debt", "cash", "short_term_investments"],
    notes: {pt: "Aplicações restritas podem ser excluídas por decisão registrada.", en: "Restricted investments may be excluded by a recorded decision."},
  },
  {
    id: "leverage",
    version: "v1",
    labels: {pt: "Alavancagem", en: "Leverage"},
    formula: "net_debt / adjusted_ebitda_ltm",
    inputs: ["net_debt", "adjusted_ebitda_ltm"],
    notes: {pt: "LTM sempre derivado (anual anterior + YTD atual − YTD anterior).", en: "LTM is always derived (prior annual + current YTD − prior YTD)."},
  },
];

export const financialDefinitionMap: ReadonlyMap<string, FinancialDefinition> = new Map(financialDefinitions.map((d) => [d.id, d]));

export function financialDefinition(id: string): FinancialDefinition {
  const found = financialDefinitionMap.get(id);
  if (!found) throw new Error(`unknown financial definition: ${id}`);
  return found;
}

packages/financial-core/src/contractual-.content:
import {createHash} from "node:crypto";

import {calculateImpliedEbitda, calculateLeverage} from "./credit-math";
import {aggregateDebtViews} from "./financial-truth";
import {calculateCovenantHeadroom} from "./structure";
import Decimal from "decimal.js";
import {z} from "zod";

/**
 * Executor of the method `reconcile-covenant-definitions` (v14, after the thirteenth independent review).
 * It never writes "breached". Each indenture carries the anchor of its definitions and one anchor per
 * tier; EBITDA adjustments are typed (denominator additions versus numerator obligations) and never
 * folded together; the net debt of each instrument is computed from that instrument's own component
 * list over dated component values with their own anchors, so a definition that adds leases or drops
 * derivatives changes the number or refuses the comparison; the reported index is comparable only at
 * the as-of date, with the same components and an opened EBITDA value; an ordinary settlement needs
 * its date (so does an accelerated one); the next measurement follows the frequency the indenture
 * states; every unproven tier leaves a written condition; a numerator obligation (sellers finance) is
 * modeled with its own value or left as a legal condition, never folded into the EBITDA declaration;
 * a legal condition on the numerator caps comparability; component lines, EBITDA and opening carry a
 * unit and a twelve-month period. Net debt, leverage and headroom run through financial-core.
 */
const ratio = z.string().regex(/^\d+(\.\d+)?$/);
const money = z.string().regex(/^-?\d+(\.\d+)?$/);
const nonNegative = z.string().regex(/^\d+(\.\d+)?$/);
const unitSchema = z.enum(["BRL", "BRL thousand", "BRL million", "USD", "USD thousand"]);
const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);
/** An indenture anchor cites a numbered clause (4.22.3(j), 7.24.3(VIII)); a label such as "índice financeiro" is not a clause. */
const indentureAnchorSchema = z.object({document: z.string().min(1), clause: z.string().regex(/\d+(\.\d+)+/, "an indenture anchor needs a numbered clause"), page: z.number().int().positive()}).strict();
const anchorSchema = z.object({document: z.string().min(1), clause: z.string().optional(), page: z.number().int().positive().optional(), note: z.string().optional()}).strict();
type Anchor = z.infer<typeof anchorSchema>;

/** The components a net debt definition is built from; comparability is decided on these, not on prose. */
export const netDebtComponentSchema = z.enum([
  "loans_and_financings", "debentures", "derivative_liabilities", "other_onerous_debt", "leases",
  "cash_and_equivalents", "financial_investments", "derivative_assets",
]);
type NetDebtComponent = z.infer<typeof netDebtComponentSchema>;
const DEDUCTIONS = new Set<NetDebtComponent>(["cash_and_equivalents", "financial_investments", "derivative_assets"]);
/** The words a clause uses for each component; a structured component the text never names is a tag, not a definition. */
const COMPONENT_WORDS: Record<NetDebtComponent, RegExp> = {
  loans_and_financings: /emprestim|financiament|loan|borrowing|divida bruta|gross debt/,
  debentures: /debenture|divida bruta|gross debt/,
  derivative_liabilities: /derivativ|derivative/,
  other_onerous_debt: /outra|other|onerosa|onerous/,
  leases: /arrendament|lease/,
  cash_and_equivalents: /caixa|disponibilidade|cash/,
  financial_investments: /aplicac|investment/,
  derivative_assets: /derivativ|derivative/,
};
/** An open-ended residual ("qualquer outra dívida onerosa"): its absence from the base is a condition, not a mismatch. */
const RESIDUAL: NetDebtComponent = "other_onerous_debt";


export const covenantTierSchema = z.object({
  limit: ratio,
  condition: z.discriminatedUnion("type", [
    z.object({type: z.literal("unconditional")}).strict(),
    z.object({type: z.literal("until_reference_settled"), referenceInstruments: z.array(z.string().min(1)).min(1)}).strict(),
    z.object({type: z.literal("after_reference_settled"), referenceInstruments: z.array(z.string().min(1)).min(1)}).strict(),
  ]),
  anchor: indentureAnchorSchema,
}).strict();

/** Adjustments beyond the base EBITDA definition, typed by the side of the ratio they touch. */
export const ebitdaAdjustmentSchema = z.object({
  id: z.string().min(1),
  kind: z.enum(["denominator_addition", "numerator_obligation", "other"]),
  description: z.string().min(1),
  anchor: indentureAnchorSchema,
  /** For a numerator obligation: its dated value in the base with its unit, or null when the base does not state it. */
  obligation: z.object({value: nonNegative, unit: unitSchema, asOf: isoDate, anchor: anchorSchema}).strict().nullable().default(null),
}).strict();

export const covenantInstrumentSchema = z.discriminatedUnion("source", [
  z.object({
    source: z.literal("indenture"),
    id: z.string().min(1),
    indexName: z.string().min(1),
    direction: z.enum(["maximum", "minimum"]).default("maximum"),
    netDebtDefinition: z.string().min(1),
    /** The perimeter the definition measures; the reported index must match it to be comparable. */
    perimeter: z.enum(["consolidated", "parent"]).default("consolidated"),
    netDebtComponents: z.array(netDebtComponentSchema).min(1),
    ebitdaDefinition: z.string().min(1),
    ebitdaAdjustments: z.array(ebitdaAdjustmentSchema).default([]),
    measurement: z.object({frequency: z.enum(["annual", "semiannual", "quarterly"]), basis: z.string().min(1), fiscalYearEnd: z.string().regex(/^\d{2}-\d{2}$/)}).strict(),
    /** Tiers in the order the indenture states them. */
    tiers: z.array(covenantTierSchema).min(1),
    /** One anchor per definition: the net debt clause and the EBITDA clause sit on different pages. */
    definitionAnchors: z.object({netDebt: indentureAnchorSchema, ebitda: indentureAnchorSchema}).strict(),
  }).strict(),
  z.object({
    source: z.literal("trustee_report"),
    id: z.string().min(1),
    indexName: z.string().min(1),
    reportedLimit: ratio,
    reportedMeasurement: z.object({value: ratio, asOf: isoDate}).strict().nullable().default(null),
    anchor: anchorSchema,
  }).strict(),
]);

/** One line of the base with the components it covers (an aggregated note line may cover two), its date and its own anchor. */
export const componentValueSchema = z.object({
  component: netDebtComponentSchema,
  covers: z.array(netDebtComponentSchema).min(1),
  value: nonNegative,
  unit: unitSchema,
  perimeter: z.enum(["consolidated", "parent"]).default("consolidated"),
  asOf: isoDate,
  anchor: anchorSchema,
}).strict();

export const covenantReconciliationInputSchema = z.object({
  asOfDate: isoDate,
  /** The unit of every monetary value in the base; lines, EBITDA and openings must state the same. */
  unit: unitSchema,
  /** Where the source states the unit; its note must name that unit, so a relabelled scale is refused. */
  unitAnchor: anchorSchema.extend({note: z.string().min(1)}),
  instruments: z.array(covenantInstrumentSchema),
  referenceSettlements: z.array(z.object({
    instrument: z.string().min(1),
    maturityDate: isoDate,
    /** ordinary: settled in the ordinary course (needs the date); accelerated: settled by acceleration; outstanding: still alive; unknown: the base does not say. */
    settlement: z.enum(["ordinary", "accelerated", "outstanding", "unknown"]),
    settlementDate: isoDate.nullable().default(null),
    anchor: anchorSchema,
  }).strict()).default([]),
  componentValues: z.array(componentValueSchema).default([]),
  /** Dated lines of the base that may belong to a numerator obligation (acquisition payables, contingent consideration) but are not yet classified; they are carried as uncovered terms, never added and never called absent. */
  candidateObligations: z.array(z.object({id: z.string().min(1), description: z.string().min(1), value: nonNegative, unit: unitSchema, asOf: isoDate, relatedAdjustmentId: z.string().min(1).nullable().default(null), anchor: anchorSchema}).strict()).default([]),
  /** LTM EBITDA as the company computes it for the covenant, when it is opened, with the adjustment ids it already incorporates. */
  ltmEbitda: z.object({value: money, unit: unitSchema, perimeter: z.enum(["consolidated", "parent"]).default("consolidated"), asOf: isoDate, months: z.literal(12), incorporatesAdjustments: z.array(z.string().min(1)).default([]), anchor: anchorSchema}).strict().nullable().default(null),
  reported: z.object({
